/* 💰📅 THE FINAL PRICE AFTER ASSEMBLY IS AUTHORITATIVE (owner 2026-09-09) — a split drop-off's bags each
   round their own tax, so recording each bag's own rounded due sums a penny off what the card was actually
   charged (pickupDue = totals summed THEN rounded once). Found live by cardpointe-reconcile. The pickup now
   gives the rounding remainder to the last bag so the recorded rows sum EXACTLY to the charge. */
section('— 💰 a split drop-off records EXACTLY what the card was charged (no penny drift) —');
run(`
  window.__stAT = storeById(1).tax; storeById(1).tax = 0.10;   // a rate that makes two 0.05 bags drift a penny
  DB.drawers={}; DB.drawers[homeStore()+'|x'] = { status:'open', open:{ by:'M', at:1000, total:200, counts:{} } };
  DB.customers.push({ id:'PENC', first:'Penny', last:'Split', mainStore:1, balance:0, prefs:{} });
  DB.orders.push({ id:'PENA', number:'PEN-A', customerId:'PENC', storeId:1, status:'Ready', bagOf:'PEN-DROP', pieceCount:1, splits:[], orderUpcharges:[], paymentStatus:'unpaid', createdAt:1, lines:[{ item:'S', price:0.05 }] });
  DB.orders.push({ id:'PENB', number:'PEN-B', customerId:'PENC', storeId:1, status:'Ready', bagOf:'PEN-DROP', pieceCount:1, splits:[], orderUpcharges:[], paymentStatus:'unpaid', createdAt:1, lines:[{ item:'S', price:0.05 }] });
  __penDue = pickupDue('PENC');
  __penPre = (Math.round(computeTotals(order('PENA')).total*100) + Math.round(computeTotals(order('PENB')).total*100))/100;   // the OLD per-bag-rounded sum
  modal=function(){}; window.__payMeta=null; payPickup('PENC','Cash','');
  __penPaid = Math.round((DB.payments||[]).filter(function(p){return ['PENA','PENB'].indexOf(p.orderId)>=0;}).reduce(function(a,b){return a+(b.amount||0);},0)*100)/100;
`);
check('💰 the fixture really drifts — per-bag rounding would book more than the single charge (negative control)', "__penPre > __penDue");
check('💰 the recorded payments sum to EXACTLY pickupDue — the amount the card was charged', "Math.abs(__penPaid - __penDue) < 1e-9");
check('💰 ...and both bags were still handed over', "order('PENA').status==='PickedUp' && order('PENB').status==='PickedUp'");
check('💰 the fix is wired through pickupDue, not a private re-sum (source pin)', "__APPSRC.indexOf('const __grand=pickupDue(cid)')>0");
run("storeById(1).tax=window.__stAT; delete window.__stAT; DB.customers=DB.customers.filter(function(c){return c.id!=='PENC';}); DB.orders=DB.orders.filter(function(o){return ['PENA','PENB'].indexOf(o.id)<0;}); DB.payments=(DB.payments||[]).filter(function(p){return ['PENA','PENB'].indexOf(p.orderId)<0;}); DB.drawers={};");


/* 💰🧾 …AND AN ACCOUNT PICKUP BILLS EACH ORDER ITS OWN WORTH. There is no single charge to match on account —
   the statement adds the orders up — so the absorbed penny only made one order's ledger charge exceed the
   order, which is precisely what MON-2 forbids. It went red live on 2026-09-17 (Danforth's 3-09-17-26-3001
   billed $68.06 against $68.05, its sibling a cent light, the pair correct). */
run(`
  window.__stAT2 = storeById(2).tax; storeById(2).tax = 0.095;   /* the real Hot Springs rate — the live MON-2 case */
  DB.drawers={}; DB.drawers[homeStore()+'|x'] = { status:'open', open:{ by:'M', at:1000, total:200, counts:{} } };
  DB.customers.push({ id:'PENAC', first:'Penny', last:'Account', mainStore:2, balance:0, isAccount:true, prefs:{} });
  /* two orders whose own totals round DOWN while the pair rounds UP: 62.15 → 68.05, 41.60 → 45.55, together 113.61 */
  DB.orders.push({ id:'PACA', number:'PAC-A', customerId:'PENAC', storeId:2, status:'Ready', pieceCount:1, splits:[], orderUpcharges:[], paymentStatus:'unpaid', createdAt:1, lines:[{ item:'S', price:62.15 }] });
  DB.orders.push({ id:'PACB', number:'PAC-B', customerId:'PENAC', storeId:2, status:'Ready', pieceCount:1, splits:[], orderUpcharges:[], paymentStatus:'unpaid', createdAt:1, lines:[{ item:'S', price:41.60 }] });
  __pacWorth = { A: computeTotals(order('PACA')).total, B: computeTotals(order('PACB')).total };
  __pacDrift = (Math.round(__pacWorth.A*100)+Math.round(__pacWorth.B*100))/100 !== pickupDue('PENAC');   /* the control: the pair really does round differently */
  modal=function(){}; window.__payMeta=null; payPickup('PENAC','Account','');
  __pacLed = (DB.ledger||[]).filter(function(e){ return ['PACA','PACB'].indexOf(e.orderId)>=0 && e.type==='charge'; }).map(function(e){ return {o:e.orderId, amt:e.amount}; });
`);
check('🧾 the fixture really drifts — the pair rounds to a different cent than the two orders do (negative control)', '__pacDrift');
check('🧾 an ACCOUNT pickup bills each order exactly what that order is worth — never a penny more (MON-2)', "__pacLed.length===2 && __pacLed.every(function(r){ var w=Math.round(__pacWorth[r.o==='PACA'?'A':'B']*100)/100; return Math.abs(r.amt - w) < 1e-9; })");
check('🧾 ...and the account is billed the two together, nothing lost between them', "Math.abs(__pacLed.reduce(function(a,b){return a+b.amt;},0) - (Math.round(__pacWorth.A*100)+Math.round(__pacWorth.B*100))/100) < 1e-9");
check('🧾 the card/cash path still absorbs the rounding remainder — only Account is exempt (source pin)', "__APPSRC.indexOf(\"__last>=0 && method!=='Account'\")>0");
run("storeById(2).tax=window.__stAT2; delete window.__stAT2; DB.customers=DB.customers.filter(function(c){return c.id!=='PENAC';}); DB.orders=DB.orders.filter(function(o){return ['PACA','PACB'].indexOf(o.id)<0;}); DB.ledger=(DB.ledger||[]).filter(function(e){return ['PACA','PACB'].indexOf(e.orderId)<0;}); DB.payments=(DB.payments||[]).filter(function(p){return ['PACA','PACB'].indexOf(p.orderId)<0;}); DB.drawers={};");

section('— arBill: debt goes ON the books exactly once, rounded, stamped —');
