/* Owner 2026-09-11: "pre-load the date... 99.9% of clock-ins and outs are same day." A blank clock-out in the
   Edit time-entry modal now pre-fills the clock-in's DATE, so the manager only sets the time. */
run(`
  __ecMod=modal; __ecCap=''; modal=function(h){ __ecCap=String(h); };
  __ecCan=can; can=function(){ return true; };
  __ecX={ id:'ECX', empId:(DB.employees[0]||{}).id, in:new Date(2026,8,11,9,0).getTime() };   // OPEN entry, no clock-out
  DB.timeclock=DB.timeclock||[]; DB.timeclock.push(__ecX);
  editClock('ECX', Date.now());
  __ecCoVal=(function(){ var m=__ecCap.match(/id="co"[^>]*value="([^"]*)"/); return m?m[1]:'<none>'; })();
  __ecInVal=(function(){ var m=__ecCap.match(/id="ci"[^>]*value="([^"]*)"/); return m?m[1]:''; })();
  __ecPre=(__ecCoVal.indexOf('2026-09-11')===0 && __ecCoVal.length>=16 && __ecCoVal.indexOf('2026-09-11')===__ecInVal.indexOf('2026-09-11'));
  __ecNotBefore=(__ecCoVal.slice(0,16) >= __ecInVal.slice(0,16));   // never defaults BEFORE the clock-in
  DB.timeclock=DB.timeclock.filter(function(e){ return e.id!=='ECX'; });
  modal=__ecMod; can=__ecCan;
`);
check('⏱ a blank clock-out pre-loads the clock-in DATE (manager just sets the time)', "__ecPre");
check('⏱ ...and the pre-filled time never lands before the clock-in', "__ecNotBefore");

