section('🏷 bag numbers carry the drop-off — <order>-NN suffix, traceable + collision-safe (owner 2026-08-22)');
run(`
  DB.customers.push({ id:'BNC', first:'Bag', last:'Number', phone:'5015550061', mainStore:1, prefs:{} });
  DB.orders.push({ id:'BNO', number:'1-08-22-26-0044', customerId:'BNC', storeId:1, status:'In Process', pieceCount:3, createdAt:1, _t:1, orderUpcharges:[],
    lines:[{id:'bn1',priceId:null,desc:'a',price:10,assembled:true,bag:null,upcharges:[]},{id:'bn2',priceId:null,desc:'b',price:10,assembled:true,bag:null,upcharges:[]},{id:'bn3',priceId:null,desc:'c',price:10,assembled:true,bag:null,upcharges:[]}] });
  __bno=order('BNO');
  __bnA=asmSpinOff(__bno,[__bno.lines[0]],{});
  __bnB=asmSpinOff(__bno,[__bno.lines[0]],{});
`);
check('the first bag is <drop-off>-01', "__bnA.number==='1-08-22-26-0044-01'");
check('the second bag is <drop-off>-02', "__bnB.number==='1-08-22-26-0044-02'");
check('each bag remembers its drop-off (bagOf), and its pieces carry the new invoice number', "__bnA.bagOf==='1-08-22-26-0044' && __bnA.lines[0].bag==='1-08-22-26-0044-01'");
check('bag numbers stay UNIQUE (a checked invariant)', "(function(){ var seen={},dup=false; (DB.orders||[]).forEach(function(o){ if(seen[o.number]) dup=true; seen[o.number]=1; }); return !dup; })()");
/* ⚠️ findByScan must land a suffixed bag ticket on the CHILD (case 2, full order number, runs BEFORE the
   split/fallback cases) and the bare drop-off number on the parent — the whole reason this numbering is safe. */
check('scanning a bag ticket 1-08-22-26-0044-02 resolves to THAT bag, not the drop-off', "(findByScan('1-08-22-26-0044-02')||{}).order===__bnB");
check('scanning the bare drop-off number still resolves to the parent', "(findByScan('1-08-22-26-0044')||{}).order===__bno");
run("__bnTxt=receiptText(__bnB, cust('BNC'), null);");
check('the bag invoice spells out its drop-off + position', "__bnTxt.indexOf('part of drop-off 1-08-22-26-0044')>=0 && __bnTxt.indexOf('bag 02')>=0");
check('...and the barcode extractor still reads the bag order number from the ticket', "bcFromText(__bnTxt)==='1-08-22-26-0044-02'");
run("DB.orders=DB.orders.filter(function(o){ return ['BNO'].indexOf(o.id)<0 && o.bagOf!=='1-08-22-26-0044'; }); DB.customers=DB.customers.filter(function(c){ return c.id!=='BNC'; });");

