  "__inN=new Date(2026,8,3,9,0).getTime(); __outN=new Date(2026,8,3,17,0).getTime();",
  "addTimeAck('TACK1','edit','old','new',{id:'OWNER1',name:'Blake'},{inWas:__iw,outWas:__ow,inNow:__inN,outNow:__outN});",
