  "__sentClear=(__sent.indexOf('You clocked in and out on')>=0 && __sent.indexOf('adjusted')>=0 && __sent.indexOf('8.5 hours')>=0 && __sent.indexOf('8 hours')>=0);",
  "__oldEmp3=state.employeeId; __oldGo4=go; go=function(){}; __oldSess2=saveSession; saveSession=function(){}; window.__ehArmAt=0;",
  "clockInCommit('TACK1','home');",
  "__punchBlocked=!openClock('TACK1');",
  "__oldVal2=val; val=function(id){ return id==='tackpin' ? '0000' : __oldVal2(id); };",
  "timeAckGateSign('TACK1','home');",
  "__wrongPinBlocked=!openClock('TACK1') && pendingTimeAcks('TACK1').length===1;",
  "val=function(id){ return id==='tackpin' ? '8888' : __oldVal2(id); };",
  "timeAckGateSign('TACK1','home');",
  "__signedAndIn=!!openClock('TACK1') && pendingTimeAcks('TACK1').length===0;",
  "__signLogged=DB.activity.some(function(a){return String(a.type||'')==='PAYROLL SIGN-OFF' && String(a.detail||'').indexOf('at clock-in')>=0;});",
  "val=__oldVal2;",
  "__saveEmp2=state.employeeId; clockOutCommit('TACK1'); state.employeeId=__saveEmp2;",
  "window.__ehOutArmAt=0; clockOutCommit('TACK1');",
  "clockInCommit('TACK1','home'); __cleanPunchWorks=!!openClock('TACK1');",
