  DB.orders.push({ id:'NHD', number:'NH-4', customerId:'DUP1', storeId:1, status:'Detailed', orderUpcharges:[], splits:[],
    lines:[{ id:'nhd1', hsl:'10088001', priceId:null, upcharges:[] }], _t:1 });   // the same garment, back with a faded tag
  __rtT=toast; toast=function(){}; __rtCM=closeModal; closeModal=function(){}; __rtGo=go; go=function(){}; __rtDL=detailLine; detailLine=function(){};
