/* Owner 2026-09-12: 3 identical walk-in records (same name + same phone) got created. An exact name+phone
   match at intake is the SAME person — block it even under "Add anyway"; use existing or change the phone. A
   same-name-but-different-phone stays a soft prompt (distinct people are never force-blocked). */
section('— 🔁 duplicate customer guard: same name + same phone can’t be created —');
run(`
  __bmDP=dupeCustomerPrompt; __bmCalls=[]; dupeCustomerPrompt=function(dupes,v,exact){ __bmCalls.push({n:(dupes||[]).length,exact:!!exact}); };
  __bmNR=custNewRead; custNewRead=function(){ return {}; };
  __bmVal=val; val=function(id){ return { efirst:'Dupe', elast:'Guardtest', ebn:'', eemail:'', ems:'1' }[id]||''; };
  /* the stock document stub answers EVERY getElementById .checked truthy, so saveCustomer would think this is a
     business with no name and bail before the guard. Swap document for a Proxy that says ebiz is UNticked (the
     same reassignment pattern the bulk-picker test uses — a plain property set gets swallowed by the stub). */
  __bmDoc=document;
  document=new Proxy({},{ get:function(t,k){ if(k==='getElementById') return function(id){ return id==='ebiz'?{checked:false}:__bmDoc.getElementById(id); }; return __bmDoc[k]; }, set:function(){ return true; } });
  __bmEph=window.__eph;
  DB.customers.push({ id:'BM_EXIST', first:'Dupe', last:'Guardtest', phone:'8705550199', prefs:{}, _t:1 });
  __bmN0=DB.customers.length;
  window.__eph=[{ number:'8705550199' }]; window.__newForce=true;   // exact match, and force is ON
  saveCustomer('__new');
  __bmExactBlocked=(__bmCalls.length===1 && __bmCalls[0].exact===true && DB.customers.length===__bmN0);
  __bmCalls=[]; window.__eph=[{ number:'8705551234' }]; window.__newForce=false;   // same name, DIFFERENT phone
  saveCustomer('__new');
  __bmSoft=(__bmCalls.length===1 && __bmCalls[0].exact===false);
  DB.customers=DB.customers.filter(function(c){ return c.id!=='BM_EXIST'; });
  document=__bmDoc;
  window.__eph=__bmEph; val=__bmVal; custNewRead=__bmNR; dupeCustomerPrompt=__bmDP; window.__newForce=false;
`);
check('🔁 exact name+phone dup is blocked even with "Add anyway" — exact prompt, no new record', "__bmExactBlocked");
check('🔁 ...but same name + DIFFERENT phone is still a soft prompt (distinct people never force-blocked)', "__bmSoft");
check('🔁 the exact-match guard runs before the force check and skips merged tombstones (source pin)',
  "(function(){ var i=__APPSRC.indexOf('function saveCustomer('); var seg=__APPSRC.slice(i,i+1800); return seg.indexOf('_exact')>=0 && seg.indexOf('!x.mergedInto')>=0 && seg.indexOf('custNewRead(), true')>=0; })()");

