  __mgOk=(__mgA.status==='merged' && __mgA.mergedInto==='MGB' && __mgB.counts.total===5 && __mgB.counts.WT===3 && __mgB.orderIds.indexOf('MGO1')>=0 && order('MGO1').batchId==='MGB');
