check('⚠️ ...and an OVER count too - either direction is worth knowing', "wizBump('pieces',9-(+wizMe().pieces||0)); wizCountNote().indexOf('3 pieces MORE')>=0");
check('🚚 the driver count is written onto every order AND _t-stamped', "wizBump('pieces',6-(+wizMe().pieces||0)); wizConfirmed(); var o=order('WZO1'); !!o.driverCount && o.driverCount.pieces===6 && o._t>0");
check('⚠️ ...the stamp matters: an unstamped count loses the merge exactly like the 8/12 delivery did', "var i=__APPSRC.indexOf('function wizStampCount'); var seg=__APPSRC.slice(i, i+4000); seg.indexOf('_t=hlcNow()')>0");
check('🚚 confirming moves to CHECKOUT', "wizGet().step==='checkout'");
