check('⚠️ none writes no payment row and bills nothing - open===0 already handled it', "var i=__APPSRC.indexOf('function routeCheckout'); var seg=__APPSRC.slice(i, i+6500); seg.indexOf('if(open>0){')>0 && seg.indexOf(\"else { o.paymentStatus='paid'; }\")>0");
