/* ↩🔒 THE REFUND DOUBLE-CLICK RACE (8/28 readiness review). refundReqComplete's status check happens BEFORE
   the network answers, so two clicks both passed it and sent two reversals. The guard lives on the WINDOW
   (the o._delivering lesson: a synced in-flight flag can strand a record), and it is proven behaviourally:
   payRefund is stubbed to a never-resolving promise — the customer's bank is still thinking — and the second
   call must send NOTHING. */
console.log('- refund race: one reversal in flight per payment -');
run(`
  DB.customers.push({id:'cRF', first:'Refund', last:'Race', _t:hlcNow()});
  DB.orders.push({id:'oRF', number:'1-08-28-26-0090', customerId:'cRF', storeId:1, status:'PickedUp', paymentStatus:'paid', lines:[], createdAt:Date.now(), _t:hlcNow()});
  DB.payments.push({id:'pRF', orderId:'oRF', amount:20, method:'Card', txn:'RTX1', date:Date.now(), storeId:1, brand:'Visa', last4:'1111'});
  window.__rfCalls=0; window.__rfIdem=null;
  window.__realPayRefund=payRefund; window.__realProviderId=payProviderId;
  payRefund=function(ref,cents,ctx){ window.__rfCalls++; window.__rfIdem=(ctx&&ctx.idem)||''; return new Promise(function(){}); };
  payProviderId=function(){ return 'sim'; };
  _refundMoney('oRF','pRF',20,'race test', function(){}, {idem:'refund|REQX|2000'});
  _refundMoney('oRF','pRF',20,'race test', function(){}, {idem:'refund|REQX|2000'});
`);
