check('🛍 OK clears it from the list, logged — and the debt itself is untouched', "order('PNO').pnpReview.status==='ok' && pendingPnpReviews().length===0 && cust('PNC').balance===__pnDue && (DB.activity||[]).some(function(a){ return a.type==='PNP reviewed' && a.detail.indexOf('PN-1')>=0; })");
