/* 🛣 THE PAGE TALKS TO THE HUB DIRECTLY when the shell says where it is (2026-08-19).
   The shell's proxy stripped accept-encoding, so every station pulled 5,018 KB instead of 427 KB per sync.
   The deeper fix is not to sit in the middle at all. */
section('🛣 the hub address the page actually calls');
run("__ab0 = (function(){ try { return localStorage.getItem('ozarkpos_hubapi'); } catch(e){ return null; } })();");
check('with nothing set, it uses the page own origin — exactly what a browser station does',
  "(function(){ try{ localStorage.removeItem('ozarkpos_hubapi'); }catch(e){} return hubApiBase()===location.origin; })()");
check('⚠️ when the shell names the hub, the page calls the hub DIRECTLY instead of through the shell proxy',
  "(function(){ try{ localStorage.setItem('ozarkpos_hubapi','https://hub.example.com'); }catch(e){} return hubApiBase()==='https://hub.example.com'; })()");
check('...a trailing slash is tolerated, because a config file written by a human will have one',
  "(function(){ try{ localStorage.setItem('ozarkpos_hubapi','https://hub.example.com/'); }catch(e){} return hubApiBase()==='https://hub.example.com'; })()");
check('⚠️ a value with a PATH is refused — an origin only, so a stray setting cannot redirect the shop money calls',
  "(function(){ try{ localStorage.setItem('ozarkpos_hubapi','https://evil.example.com/steal'); }catch(e){} return hubApiBase()===location.origin; })()");
check('⚠️ ...and so is a non-http scheme',
  "(function(){ try{ localStorage.setItem('ozarkpos_hubapi','javascript:alert(1)'); }catch(e){} return hubApiBase()===location.origin; })()");
check('...and junk falls back to the origin rather than breaking sync',
  "(function(){ try{ localStorage.setItem('ozarkpos_hubapi','  '); }catch(e){} var a=hubApiBase(); try{ localStorage.setItem('ozarkpos_hubapi','not a url'); }catch(e){} return a===location.origin && hubApiBase()===location.origin; })()");
check('a host with a PORT is accepted, since a test hub runs on one',
  "(function(){ try{ localStorage.setItem('ozarkpos_hubapi','http://127.0.0.1:8090'); }catch(e){} return hubApiBase()==='http://127.0.0.1:8090'; })()");
check('⚠️ syncInit uses it — the whole point; setting the value must actually change where calls go',
  "var i=__APPSRC.indexOf('function syncInit('); __APPSRC.slice(i,i+120).indexOf('SYNC.apiBase=hubApiBase()')>0");
run("try{ if(__ab0===null) localStorage.removeItem('ozarkpos_hubapi'); else localStorage.setItem('ozarkpos_hubapi', __ab0); }catch(e){}");
check('the hub-address fixture was restored',
  "(function(){ try{ return (localStorage.getItem('ozarkpos_hubapi')||null)===__ab0; }catch(e){ return true; } })()");

section('⏱ the stale-shift threshold is ONE number, in two files');
/* ⚠️ check-invariants.js gained PAY-1 on 2026-08-19 because the app's own stale-shift alarm is gated
   `if(isOwner())` on Home — so it only ever reached an owner who happened to be signed in, standing at a
   station. One employee sat clocked in for 28 hours and it reached nobody.
   The checker therefore carries its own copy of the 24h threshold, and two copies of one number drift. When
   they drift the checker contradicts the screen and people stop believing both. Same guard as the SHAPE list
   and the mirror block: read BOTH files and fail if they disagree. */
{
  /* ⚠️ Computed in HARNESS scope and asserted in the SANDBOX. check(name, expr) runs `expr` inside the vm,
     where `__APPSRC` lives but `require` does not — the first version passed a harness-scope value as the
     expression and crashed the whole run. And no regex: this text passes through a shell on the way here,
     and the version before that lost its escapes and asserted an error message. */
  const _fs = require('fs');
  const _val = src => {
    let i = src.indexOf('LONG_OPEN_MS');
    while (i >= 0) {
      const eq = src.indexOf('=', i), semi = src.indexOf(';', i);
      if (eq > 0 && semi > eq) {
        const t = src.slice(eq + 1, semi).split(' ').join('').split(String.fromCharCode(9)).join('');
        let clean = t.length > 0;
        for (const ch of t) if ('0123456789*'.indexOf(ch) < 0) clean = false;   /* digits and * only */
        if (clean) return t;
      }
      i = src.indexOf('LONG_OPEN_MS', i + 1);
    }
    return '';
  };
  const _app = _val(_fs.readFileSync(file, 'utf8'));
  const _chk = _val(_fs.readFileSync('check-invariants.js', 'utf8'));
  run('__thrApp=' + JSON.stringify(_app) + '; __thrChk=' + JSON.stringify(_chk) + ';');
  check('⚠️ the app and check-invariants agree on what "too long to be real" means  [app=' + (_app||'?') + ' checker=' + (_chk||'?') + ']',
    "!!__thrApp && !!__thrChk && __thrApp===__thrChk");
  check('...and it is 24 hours, the number the screen shows staff', "__thrApp==='24*3600000'");
}

section('🛠 a Chrome station applies the settings set from the production desk');
/* The two per-origin settings that decide whether a counter prints and on which paper had to be EYEBALLED at
   the desk (8/21 todos at both counters). Now the page takes them from the hub's station-config row through
   the app's own setters. Behavioural: stationCfgApply and stationCfgPoll are the real functions; only fetch
   and the toasts are stubbed. */
run("__cfgFetches=[]; __cfgFetchWas=fetch; __cfgWant={stationName:'Arkadelphia Counter',storeScope:1,printAgent:true}; __cfgAt=12345;"
  + " fetch=function(u,o){ __cfgFetches.push({u:String(u),o:o||{}}); if(String(u).indexOf('/api/station-config?id=')>0) return Promise.resolve({json:function(){ return Promise.resolve({ok:true,want:__cfgWant,cfgAt:__cfgAt}); }}); return Promise.resolve({json:function(){ return Promise.resolve({ok:true}); }}); };"
  + " __toastWas=toast; toast=function(){}; SYNC.on=true; SYNC.apiBase='http://hub.test';"
  + " localStorage.setItem('ozarkpos_ws',JSON.stringify({id:'WS-TESTCFG',name:'Old Name'})); localStorage.setItem('ozarkpos_allstores','1'); state.allStores=true; localStorage.setItem('ozarkpos_useagent','0'); localStorage.removeItem('ozarkpos_cfgapplied'); window.__cfgPollAt=0;");
/* guarded so the NEGATIVE CONTROL (an app without these functions) fails readably instead of crashing the run */
run("__cfgRes=(typeof stationCfgApply==='function')?stationCfgApply(__cfgWant):{applied:{},refused:[]};");
check('🛠 the store scope is applied through the REAL setter — the screen repaints, it is not a hidden key write',
  "state.allStores===false && state.store===1 && localStorage.getItem('ozarkpos_allstores')==='0'");
check('...the local print agent toggle too', "useAgentHere()===true && __cfgRes.applied.printAgent===true");
check('...and the station name', "JSON.parse(localStorage.getItem('ozarkpos_ws')).name==='Arkadelphia Counter' && JSON.parse(localStorage.getItem('ozarkpos_ws')).id==='WS-TESTCFG'");
check('...nothing was refused in a clean want', "__cfgRes.refused.length===0");
run("__cfgRes2=(typeof stationCfgApply==='function')?stationCfgApply({hubUrl:'https://evil.example.com', hubKey:'STOLEN', stationId:'WS-OTHER', printers:{1:'x'}}):{applied:{},refused:[]};");
check("⚠️ hubUrl, hubKey and stationId are REFUSED by name — the page can never be re-pointed, re-keyed or re-identified from a row",
  "__cfgRes2.refused.indexOf('hubUrl')>=0 && __cfgRes2.refused.indexOf('hubKey')>=0 && __cfgRes2.refused.indexOf('stationId')>=0 && Object.keys(__cfgRes2.applied).length===0");
check('...and the id is untouched', "JSON.parse(localStorage.getItem('ozarkpos_ws')).id==='WS-TESTCFG'");
/* the poll: once, then idempotent */
run("localStorage.setItem('ozarkpos_allstores','1'); state.allStores=true; __cfgFetches=[]; window.__cfgPollAt=0; if(typeof stationCfgPoll==='function') stationCfgPoll();");
check('the poll asks the hub for THIS station by its WS- id',
  "__cfgFetches.some(function(f){ return f.u.indexOf('/api/station-config?id=WS-TESTCFG')>0; })");
run("__cfgFetches=[]; window.__cfgPollAt=0; if(typeof stationCfgPoll==='function') stationCfgPoll();");
check('...and after applying it does not apply the same row again a minute later (idempotent on cfgAt)',
  "!__cfgFetches.some(function(f){ return f.o && f.o.method==='POST'; })");
check('⚠️ a second poll inside the minute does not even ask', "(function(){ if(typeof stationCfgPoll!=='function') return false; var n=__cfgFetches.length; stationCfgPoll(); return __cfgFetches.length===n; })()");
run("fetch=__cfgFetchWas; toast=__toastWas; localStorage.removeItem('ozarkpos_cfgapplied'); localStorage.setItem('ozarkpos_useagent','0'); SYNC.on=false;");
check('the settings fixtures were put back', "fetch===__cfgFetchWas && useAgentHere()===false");

section('🩺 diagnostics on request — evidence, never the key, never a command');
run("localStorage.setItem('ozarkpos_huk','SECRET-KEY-VALUE'); SYNC.on=true; SYNC.apiBase='http://hub.test'; __dg=stationDiagPayload(); __dgs=JSON.stringify(__dg);");
check('🩺 the payload names the build, the sync state, the settings and the screen', "!!(__dg.sync && 'status' in __dg.sync && __dg.settings && __dg.settings.ws && 'screen' in __dg)");
check("⚠️ THE HUB KEY'S VALUE IS NEVER IN IT — only its presence as a boolean", "__dgs.indexOf('SECRET-KEY-VALUE')<0 && __dg.settings.hubKeyPresent===true");
check('...storage is reported as key NAMES only', "Array.isArray(__dg.storageKeys) && __dg.storageKeys.indexOf('ozarkpos_huk')>=0 && __dgs.indexOf('SECRET-KEY-VALUE')<0");
run("__dgPosts=[]; __dgFetchWas=fetch; fetch=function(u,o){ __dgPosts.push({u:String(u),o:o||{}}); if(String(u).indexOf('localhost:8091')>=0) return Promise.resolve({json:function(){ return Promise.resolve({ok:true,agent:'ozark-print',version:6}); }}); return Promise.resolve({json:function(){ return Promise.resolve({ok:true}); }}); }; stationDiagSend('WS-TESTDIAG');");
check('the send asks the local print agent for its own /health first', "__dgPosts.some(function(p){ return p.u.indexOf('localhost:8091/health')>=0; })");
/* the POST is two promise hops after the /health answer — let the sandbox settle, as every async section here does */
await flush();
run("__dgBody=null; (__dgPosts.filter(function(p){ return p.u.indexOf('/api/diag')>=0; })[0]||{o:{}}).o.body && (__dgBody=JSON.parse(__dgPosts.filter(function(p){ return p.u.indexOf('/api/diag')>=0; })[0].o.body));");
check('...and posts id + diag to /api/diag with the key in the HEADER, not the body', "!!__dgBody && __dgBody.id==='WS-TESTDIAG' && !!__dgBody.diag && JSON.stringify(__dgBody).indexOf('SECRET-KEY-VALUE')<0");
check("...carrying the agent's own answer", "__dgBody.diag.agent && __dgBody.diag.agent.version===6");
/* the poll only sends when the hub's request is NEWER than the last one answered */
run("localStorage.setItem('ozarkpos_diagsent','500'); __dgPosts=[]; __pollFetchWas=fetch; fetch=function(u,o){ __dgPosts.push({u:String(u),o:o||{}}); if(String(u).indexOf('/api/station-config?id=')>0) return Promise.resolve({json:function(){ return Promise.resolve({ok:true,want:null,cfgAt:1,diagAt:400}); }}); return Promise.resolve({json:function(){ return Promise.resolve({ok:true}); }}); }; window.__cfgPollAt=0; localStorage.setItem('ozarkpos_ws',JSON.stringify({id:'WS-TESTDIAG',name:'T'})); stationCfgPoll();");
check('⚠️ an OLD diagnostics request is not answered again (idempotent on diagAt)', "!__dgPosts.some(function(p){ return p.u.indexOf('/api/diag')>=0; })");
run("fetch=__dgFetchWas; localStorage.removeItem('ozarkpos_huk'); localStorage.removeItem('ozarkpos_diagsent'); SYNC.on=false;");
check('the diagnostics fixtures were put back', "fetch===__dgFetchWas && !localStorage.getItem('ozarkpos_huk')");

section('🪞 a push does not leave the station reporting drift on what it just pushed');
/* Measured live 8/21: after a station pushed an edit, the hub logged MIRROR DRIFT on exactly that collection
   with IDENTICAL row counts (hub 364 / station 364). Cause: the hub stamps every pushed record with
   _seq = the new revision and compares stations against that snapshot, but returns only {ok,rev} — so the
   station's own record kept its pre-push _seq, and mirrorFp hashes _seq. The push-success path now adopts the
   hub's _seq. Behavioural, and provable app-only because the mirror algorithm is byte-identical app↔hub:
   fingerprint the station's record after the push, fingerprint a hub-side copy at the same rev, assert equal. */
run("SYNC.on=true; SYNC.apiBase='http://hub.test'; SYNC.haveBase=true; SYNC.baseH=SYNC.baseH||{};"
  + " DB.orders=[{id:'ord_mir',number:'M-1',status:'Racked',lines:[],_t:1000,_seq:24000}];"
  + " SYNC.lastDelta={orders:[DB.orders[0]]};"
  + " __mirFetchWas=fetch; fetch=function(u,o){ return Promise.resolve({status:200, json:function(){ return Promise.resolve({s:200,j:{ok:true,rev:25573}}); }, then:undefined }); };");
/* drive the real success branch by hand: it is the body of the .then after a 200 ok */
run("(function(){ var res={s:200,j:{ok:true,rev:25573}};"
  + " if(res.j&&res.j.ok){ SYNC.rev=res.j.rev; SYNC.localDirty=false;"
  + "   if(SYNC.lastDelta){ Object.keys(SYNC.lastDelta).forEach(function(coll){ (SYNC.lastDelta[coll]||[]).forEach(function(r){ if(r&&typeof r==='object') r._seq=res.j.rev; }); }); }"
  + "   if(SYNC.lastDelta) syncBaseAfterMerge(SYNC.lastDelta);"
  + "   SYNC.lastDelta=null; } })();");
check('🪞 the pushed record adopted the hub-assigned _seq', "DB.orders.filter(function(o){return o.id==='ord_mir';})[0]._seq===25573");
/* ⚠️ the assertions below drive an inline copy of the success branch to prove the _seq→fingerprint
   relationship; THIS one proves the real app actually wires it, so a negative control fails. The 8/17
   pairing: a grep sees the line exists, the behavioural test proves the line is right. */
check('⚠️ ...and the real push-success branch stamps lastDelta with the hub rev (not just this test)',
  "(function(){ var i=__APPSRC.indexOf('what we just sent is now at the hub'); if(i<0){ i=__APPSRC.indexOf('syncBaseAfterMerge(SYNC.lastDelta)'); } var b=__APPSRC.slice(Math.max(0,i-700),i+200); return b.indexOf('SYNC.lastDelta')>0 && b.indexOf('r._seq=res.j.rev')>0; })()");
/* ⚠️ COMPARE THE SERIALIZED FINGERPRINT, not the object. mirrorFp returns {n,x,s} per collection, so
   `fp.orders === fp.orders` compares object IDENTITY and is ALWAYS false — the first version of these two
   assertions could not fail, which is not evidence. JSON.stringify makes the comparison mean what it says. */
check('⚠️ ...so the station fingerprint of that record now EQUALS the hub fingerprint of it at that revision (no drift)',
  "(function(){ var rec=DB.orders.filter(function(o){return o.id==='ord_mir';})[0]; var hubTwin=JSON.parse(JSON.stringify(rec)); return JSON.stringify(mirrorFp({orders:[rec]},{}).orders)===JSON.stringify(mirrorFp({orders:[hubTwin]},{}).orders); })()");
check('⚠️ ...and _seq IS what the fingerprint hashes — the SAME record at the pre-push _seq hashes differently, so the mismatched _seq was the drift',
  "(function(){ var rec=DB.orders.filter(function(o){return o.id==='ord_mir';})[0]; var a=JSON.stringify(mirrorFp({orders:[rec]},{}).orders); var stale=JSON.parse(JSON.stringify(rec)); stale._seq=24000; var b=JSON.stringify(mirrorFp({orders:[stale]},{}).orders); return a!==b; })()");
check('⚠️ ...and syncStamp does NOT now see it as a fresh change (no phantom re-push)', "(function(){ SYNC.needBase=false; syncStamp(); return !(SYNC.lastDelta && SYNC.lastDelta.orders && SYNC.lastDelta.orders.length); })()");
run("fetch=__mirFetchWas; DB.orders=(DB.orders||[]).filter(function(o){return o.id!=='ord_mir';}); if(SYNC.baseH) delete SYNC.baseH.orders; SYNC.on=false; SYNC.lastDelta=null;");
check('the mirror fixtures were removed', "!(DB.orders||[]).some(function(o){return o.id==='ord_mir';})");

section('🩹 a stain/damage note logged during detailing SURVIVES the next pull (the Ike Bakewell bug)');
/* Owner, 2026-08-21: "the detailed order saved, just missed a field." Traced to addStain: it pushed the note
   to l.stains and saveDB'd but did NOT stamp o._t — so the next 4-second pull merged the hub's stain-less copy
   (same _t) back over it, newcomer-wins-the-tie, and the note was gone before it ever pushed. Reproduce the
   merge and prove the fix keeps it. */
run("__stWas={val:val, captureDetail:captureDetail, detailLine:detailLine, toast:toast};"
  + " val=function(id){ return id==='dlstain' ? 'coffee, left cuff' : ''; };"
  + " captureDetail=function(){}; detailLine=function(){}; toast=function(){};"
  + " DB.orders=[{id:'ord_stain', number:'B-1', customerId:'c1', status:'Detailed', lines:[{priceId:null, desc:'Denim', stains:[]}], _t: 1000000 }];");
run("addStain('ord_stain', 0, false);");
check('🩹 the stain is on the line after logging it', "DB.orders[0].lines[0].stains.length===1 && /coffee/.test(DB.orders[0].lines[0].stains[0].note)");
check('⚠️ ...and the ORDER _t was bumped, so a same-_t hub copy can no longer out-rank it', "DB.orders[0]._t > 1000000");
/* the hub still holds the pre-stain order at the OLD _t — merge it in, exactly as a pull does */
run("__merged=syncMergeArr('orders','id', DB.orders, [{id:'ord_stain', number:'B-1', customerId:'c1', status:'Detailed', lines:[{priceId:null, desc:'Denim', stains:[]}], _t: 1000000 }]);");
check('🩹 ⚠️ after the pull merges the hub copy, the stain STILL SURVIVES (before the fix it was erased here)',
  "(__merged.filter(function(o){return o.id==='ord_stain';})[0].lines[0].stains||[]).length===1");
run("val=__stWas.val; captureDetail=__stWas.captureDetail; detailLine=__stWas.detailLine; toast=__stWas.toast; DB.orders=(DB.orders||[]).filter(function(o){return o.id!=='ord_stain';});");
check('the stain fixtures were removed', "!(DB.orders||[]).some(function(o){return o.id==='ord_stain';})");

section('📴 the service worker is registered only where it helps');
/* The worker's POLICY is proven by test-sw.js against the real sw.js. This pins the REGISTRATION rules in
   the app, which a grep can judge because they are conditions, not reachability. */
check('the app registers sw.js', "__APPSRC.indexOf(\"navigator.serviceWorker.register('sw.js')\")>0");
check('⚠️ ...never on the desktop shell (127.0.0.1 already serves from disk — a second cache with nothing to add)',
  "(function(){ var i=__APPSRC.indexOf(\"serviceWorker.register('sw.js')\"); var b=__APPSRC.slice(i-600,i); return b.indexOf(\"_h!=='127.0.0.1'\")>0 && b.indexOf(\"_h!=='localhost'\")>0; })()");
check('...and only over https from a real hub, never from a file',
  "(function(){ var i=__APPSRC.indexOf(\"serviceWorker.register('sw.js')\"); var b=__APPSRC.slice(i-600,i); return b.indexOf(\"location.protocol==='https:'\")>0 && b.indexOf('syncOn()')>0; })()");
check('...and a refusal is noted, never fatal', "(function(){ var i=__APPSRC.indexOf(\"serviceWorker.register('sw.js')\"); return __APPSRC.slice(i,i+400).indexOf('.catch(')>0; })()");

section('🧹 the app file carries no control characters');
/* ⚠️ Found 2026-08-21 by a byte scan, not by any test: asmThick's /\b(jacket|coat)\b/ had literal BACKSPACE bytes
   (0x08) where the word boundaries should be — a heredoc ate the backslashes on 8/18 — so the name-based
   jacket/coat match had been silently dead for three days while every gate stayed green. A control byte
   in a regex does not throw; it just never matches. This is the standing escape rule turned into a gate:
   nothing below 0x09 or between 0x0E and 0x1F may exist anywhere in the app file. */
check('⚠️ no control bytes in Ozark-POS.html — a backslash eaten into a backspace is a regex that silently stops matching',
  (function(){ var fs=require('fs'); var b=fs.readFileSync(file); for(var i=0;i<b.length;i++){ var c=b[i]; if(c<9||(c>13&&c<32)) return false; } return true; })() ? 'true' : 'false');
check('...and asmThick matches a jacket BY NAME again', "asmThick({priceId:null, upcharges:[], desc:''})===false && (function(){ DB.prices=DB.prices||[]; DB.prices.push({id:'pr_jk_test',name:'Sport jacket',cat:'Outerwear',price:10}); var r=asmThick({priceId:'pr_jk_test'}); DB.prices=DB.prices.filter(function(p){return p.id!=='pr_jk_test';}); return r===true; })()");

section('📬 a deferred receipt is not a failed one');
/* ⚠️ Measured 2026-08-19: ALL 103 'Delivery receipt NOT texted' rows in the live log said 'combined text
   at stop close' — the DESIGNED multi-bag path, not a failure. 103 false alarms, zero real ones, and on that
   day's route the alarm out-wrote the real sends 28 to 17. A real failure would have been invisible inside
   its own alarm. Behavioural: the real finishDelivered runs; only the SEND edges are stubbed. */
run("__cnWas=custNotify; __frbWas=finishRouteBatch; __cnAns={sent:true}; custNotify=function(){ return __cnAns; }; finishRouteBatch=function(){};");
run("DB.orders=DB.orders||[]; DB.customers=DB.customers||[];"
  + " __rc={id:'cust_rcpt', first:'Rita', last:'Receipt', phone:'5015550000'};"
  + " DB.customers.push(__rc); window.__trail=[];");
run("__mk=function(n){ var o={id:'ord_rcpt'+n, number:'T-'+n, customerId:'cust_rcpt', status:'Racked', lines:[], _t:1}; DB.orders.push(o); return o; };");
run("__cntNot=function(){ return (DB.activity||[]).filter(function(a){ return /Delivery receipt NOT/.test(a.type||''); }).length; };"
  + "__cntSent=function(){ return (DB.activity||[]).filter(function(a){ return (a.type||'')==='Delivery receipt sent'; }).length; };");

/* 1 · one order of a multi-bag stop: DEFERRED, not failed */
run("__n0=__cntNot(); window.__routeBatch={cid:'cust_rcpt', count:0, total:0, remaining:2}; finishDelivered(__mk(1), __rc, {total:10}, {});");
check('📬 a batched order writes NO alarm row — the combined text at stop close logs the real outcome',
  "__cntNot()===__n0");
check('...the deferral is on the TRAIL instead, naming the order',
  "(window.__trail||[]).some(function(e){ return e && e.kind==='receipt-deferred' && /T-1/.test(e.what||''); })");
check('...and the batch still advanced — the money path is untouched',
  "window.__routeBatch && window.__routeBatch.count===1 && window.__routeBatch.remaining===1");

/* 2 · a REAL failure still alarms — the fix must not silence the case the row exists for */
run("window.__routeBatch=null; __cnAns={sent:false, reason:'texting is off for this customer'}; __n0=__cntNot(); finishDelivered(__mk(2), __rc, {total:11}, {});");
check('⚠️ a send that was ATTEMPTED and failed still writes the alarm, with the reason',
  "__cntNot()===__n0+1 && (DB.activity||[]).some(function(a){ return /Delivery receipt NOT/.test(a.type||'') && /texting is off/.test(a.detail||''); })");

/* 3 · and a successful send still says so */
run("window.__routeBatch=null; __cnAns={sent:true}; __s0=__cntSent(); finishDelivered(__mk(3), __rc, {total:12}, {});");
check('a receipt that went out is still recorded as sent', "__cntSent()===__s0+1");

run("custNotify=__cnWas; finishRouteBatch=__frbWas; window.__routeBatch=null;"
  + " DB.orders=DB.orders.filter(function(o){ return String(o.id).indexOf('ord_rcpt')<0; });"
  + " DB.customers=DB.customers.filter(function(c){ return c.id!=='cust_rcpt'; });");
check('the receipt fixtures were removed and the stubs put back',
  "custNotify===__cnWas && !DB.customers.some(function(c){ return c.id==='cust_rcpt'; })");

section('🐾 a tap belongs on the trail, not in the log a human reads');
/* ⚠️ MEASURED on the live shop 2026-08-19, and the cost was far worse than the clutter:
     · `View` 1,677 rows + `Viewed customer` 268 = 32.4% of an activity log CAPPED at 6000, holding 19.1 days
     · logEvent() ENDS WITH saveDB(), and logView() is called from go() — so EVERY SCREEN CHANGE rewrote
       DB.activity to IndexedDB (1,073 KB serialised, 22% of the whole synced database) and set localDirty,
       which queues a hub push. On a counter that is every tap.
   The trail was built on 2026-08-10 for exactly this and its own banner forbids the path that was being used:
   "It must NOT cause a push. logEvent() calls saveDB(), and saveDB() pushes." Navigation went through it
   anyway. This is a correction to my own work, not a new idea. */
run("window.__trail=[]; state.employeeId=(DB.employees&&DB.employees[0]?DB.employees[0].id:'e1'); window.__lastView=null;"
  + " __viewRowsWas=(DB.activity||[]).filter(function(a){return (a.type||'')==='View';}).length;");
run("logView('pickup',null);");
check('🐾 a screen view is recorded on the TRAIL',
  "(window.__trail||[]).some(function(e){ return e && e.kind==='view'; })");
check('⚠️ ...and NOT in the activity log — 32% of a 19-day window was taps',
  "(DB.activity||[]).filter(function(a){return (a.type||'')==='View';}).length===__viewRowsWas");
check('⚠️ ...so navigating no longer rewrites 1 MB of activity to disk and queues a push',
  "(function(){ var i=__APPSRC.indexOf('function logView('); var b=__APPSRC.slice(i,i+900); return b.indexOf('logEvent(')<0; })()");
check('⚠️ opening a customer card is on the trail too',
  "__APPSRC.indexOf(\"trailAdd('cust-view'\")>0 && __APPSRC.indexOf(\"logEvent('Viewed customer'\")<0");
check('⚠️ but logEvent ITSELF still saves — the real log must keep landing on disk',
  "(function(){ var i=__APPSRC.indexOf('function logEvent(type,detail)'); var b=__APPSRC.slice(i,i+400); return b.indexOf('saveDB()')>0; })()");
check('...and the cap is still there, so the log can never grow without bound',
  "(function(){ var i=__APPSRC.indexOf('function logEvent(type,detail)'); return __APPSRC.slice(i,i+400).indexOf('ACT_CAP')>0; })()");   /* the magic 6000 became the ACT_CAP constant, 2026-09-10 */

section('🪞 the mirror must not call a timing gap "drift"');
/* ⚠️ 474 drift events in 9 days on the live shop, ~53 a day, and a decrypted station snapshot matched the
   hub on ALL 6,257 records in six collections — `_seq` and `_t` included. Nothing was diverging. `atRev` was
   read BEFORE mirrorFp walks the whole shop, so a pull landing inside that walk made the station describe a
   newer state while naming an older revision.
   ⚠️ THIS IS THE THIRD EXPLANATION TRIED. The first two were wrong and were disproved by measurement, not
   argued away: the stored data was byte-identical, and mirrorTick already guards on localDirty/pushing. Said
   here so the next reader does not re-run those two. */
/* ⚠️ STRING EXPRESSIONS, evaluated in the sandbox where __APPSRC lives. check(name, expr) runs `expr`
   inside the vm; a harness-scope value crashes the whole run. I made this exact mistake an hour earlier on
   the LONG_OPEN_MS guard and wrote a note about it, then made it again — so it is worth the two lines. */
check('⚠️ the revision and the fingerprint are proven to describe the SAME instant',
  "(function(){ var i=__APPSRC.indexOf('function mirrorTick('); if(i<0) return false;"
  + " var b=__APPSRC.slice(i,i+4200), fp=b.indexOf('mirrorFp(DB'), g=b.indexOf('SYNC.rev!==atRev'), p=b.indexOf('/api/mirror');"
  + " return fp>0 && g>fp && p>g; })()");
check('...and it ABORTS rather than re-reading the revision — a fresher number on a stale fingerprint is the same lie',
  "(function(){ var i=__APPSRC.indexOf('SYNC.rev!==atRev'); var b=__APPSRC.slice(i,i+90);"
  + " return b.indexOf('return')>0 && b.indexOf('atRev=')<0; })()");
check('⚠️ the two-in-a-row rule still stands — the fix must not become the thing that silences real drift',
  "__APPSRC.indexOf('SYNC.mirrorMiss>=2')>0");

section('⏰ the punch opens a screen; the screen (not a popup) is the confirmation');
/* ⚠️ 2026-08-18 4:29:33 PM, with a name on it: Bianca pressed the punch button and it clocked her IN. She
   had never clocked in that morning, and this is a TOGGLE — "no open shift" means the next press is an entry.
   The first fix was a native confirm() popup; the owner (2026-08-22) called it "extra, confusing, redundant"
   and asked for the welcome/verse screen to BE the confirmation. So a punch OPENS a screen and commits NOTHING;
   the shift starts/ends only on that screen's button (clockInCommit / clockOutCommit). Behavioural, driving the
   real empHubPunch() — only DOM edges and the two screens are stubbed. */
run("__welc=0; __outs=0; clockInWelcome=function(){__welc++;}; clockOutScreen=function(){__outs++;}; modal=function(){}; closeModal=function(){}; toast=function(){}; drawerClockoutReminder=function(){}; printTimeSlip=function(){}; saveSession=function(){}; stayEnd=function(){}; go=function(){};");
run("__valWas=(typeof val==='function')?val:null; val=function(id){ return id==='tcpin' ? 'PINTEST9' : (__valWas?__valWas(id):''); };");
run("DB.employees=(DB.employees||[]).filter(function(x){return x.id!=='emp_clocktest';}); DB.employees.push({id:'emp_clocktest',name:'Clock Tester',pin:'PINTEST9',role:'staff',active:true});");
run("DB.timeclock=[]; empHubPunch();");
check('⚠️ punching when clocked OUT opens the welcome screen, not a popup', "__welc===1");
check('...and commits NOTHING until they press the button (no accidental clock-in)', "(DB.timeclock||[]).every(function(t){ return t.empId!=='emp_clocktest'; })");

/* ⚠️ COUNT the matching rows: "Start my shift" adds EXACTLY ONE 'Clock in' row, never zero and never two
   (the idempotent guard in clockInCommit). Comparing DB.activity's LENGTH would be blind — it is capped. */
run("__logWas=(DB.activity||[]).filter(function(a){ return /Clock in/.test(a.type||a.what||'') && /Clock Tester/.test(a.detail||''); }).length;");
run("clockInCommit('emp_clocktest','home');");
check('...pressing "Start my shift" really does clock them in', "(DB.timeclock||[]).some(function(t){ return t.empId==='emp_clocktest' && !t.out; })");
check('...and logs it exactly once', "(DB.activity||[]).filter(function(a){ return /Clock in/.test(a.type||a.what||'') && /Clock Tester/.test(a.detail||''); }).length===__logWas+1");

/* ⚠️ abandoning the screen (never pressing the button) clocks nobody in — the whole point of replacing the
   popup with a screen was to KEEP this guard: an accidental punch that is closed is a safe no-op. */
run("DB.timeclock=[]; __welc=0; empHubPunch();");
check('⚠️ a punch left un-confirmed adds no entry — closing the screen is a safe no-op', "__welc===1 && (DB.timeclock||[]).length===0");

/* clocking OUT: the punch opens the end-of-shift summary; "End my shift" commits it */
run("__outs=0; DB.timeclock=[{id:'tc_ct',empId:'emp_clocktest',in:Date.now()-3*3600000,out:null,_t:1}]; empHubPunch();");
check('⚠️ punching when clocked IN opens the end-of-shift summary, not a popup', "__outs===1");
check('...and does NOT clock them out until they press "End my shift"', "!(((DB.timeclock||[])[0]||{}).out>0)");
run("clockOutCommit('emp_clocktest');");
check('...pressing "End my shift" really does clock them out', "(((DB.timeclock||[])[0]||{}).out>0)");

/* the 15-second flip-flop guards predate this and must still fire FIRST, before any screen opens */
run("__welc=0; __outs=0; DB.timeclock=[{id:'tc_ct2',empId:'emp_clocktest',in:Date.now()-3*3600000,out:Date.now()-2000,_t:1}]; empHubPunch();");
check('⏱ a punch seconds after clocking out is swallowed — no screen, no new shift', "__welc===0 && (DB.timeclock||[]).length===1 && !openClock('emp_clocktest')");

check('⚠️ the new screens speak BOTH languages — Ava reads the hub in Spanish, and a screen she cannot read just teaches her to click through',
  "['start','endShift','notYet'].every(function(k){ return EH_T.en[k] && EH_T.es[k] && EH_T.en[k]!==EH_T.es[k]; })");
check('⚠️ empHubPunch uses no prompt — prompt THROWS on the desktop app (8/18, 17 sites)',
  "(function(){ var i=__APPSRC.indexOf('function empHubPunch('); var b=__APPSRC.slice(i,i+2500); return b.indexOf('prompt(')<0; })()");
run("DB.timeclock=[]; DB.employees=(DB.employees||[]).filter(function(x){return x.id!=='emp_clocktest';}); if(__valWas) val=__valWas;");
check('the fixtures were put back — a leaked stub does not fail, it quietly stops testing',
  "!(DB.employees||[]).some(function(x){return x.id==='emp_clocktest';})");

section('🚪 the push a window makes on its way out');
/* ⚠️ THIS HAD NEVER ONCE WORKED, in Chrome or the shell. syncBeacon used navigator.sendBeacon, which
   cannot carry a header — and POST /api/db is gated on the x-ozark-key HEADER, so every one was answered 401.
   Measured in a real browser against an echo server on 2026-08-19: with application/json the preflight went
   out and the POST never followed at all, while a keepalive fetch arrived with both headers intact.
   These are BEHAVIOURAL, not source greps, because a grep can see that a line exists and not that it is
   reachable — which is exactly how the 8/17 print-agent bug and the 8/14 heat-seal bug both stayed green. */
run("__bcn=null; __fetchWas=fetch; SYNC.on=true; SYNC.apiBase='http://hub.test'; SYNC.haveBase=true; SYNC.rev=42; SYNC.lastDelta={orders:[{id:'o1',_t:1}]}; fetch=function(u,o){ __bcn={u:u,o:o||{}}; return Promise.resolve({json:function(){return Promise.resolve({});}}); };");
run("syncBeacon();");
check('a closing window now pushes at all — it never did before',
  "!!__bcn && String(__bcn.u).indexOf('/api/db')>0");
check('⚠️ ...carrying the hub key in a HEADER, which a beacon can never do',
  "!!(__bcn && __bcn.o.headers && __bcn.o.headers['x-ozark-key']!==undefined)");
check('⚠️ ...with keepalive, so the request outlives the page',
  "!!(__bcn && __bcn.o.keepalive===true)");
check('⚠️ ...and as a DELTA, not the whole ~4.6 MB database it used to send',
  "!!(__bcn && JSON.parse(__bcn.o.body).delta===true)");
check('...still with baseRev, so the hub refuses a stale unload push instead of rolling itself back',
  "!!(__bcn && JSON.parse(__bcn.o.body).baseRev===42)");

run("__bcn=null; SYNC.haveBase=false; syncBeacon(); SYNC.haveBase=true;");
check("⚠️ with no baseline it sends NOTHING — `delta:true` would be a lie the hub's own diagnostics read as evidence",
  "__bcn===null");

/* ⚠️ STUB syncStamp, do not just assign SYNC.lastDelta. syncBeacon calls syncStamp() FIRST, which
   recomputes the delta from the real DB and threw the fixture away — so the first version of this assertion
   was measuring nothing at all and failed against correct code. The cap is syncBeacon's job to enforce; what
   builds the delta is syncStamp's, and this test is about the first one. */
run("__bcn=null; __stampWas=syncStamp; syncStamp=function(){ SYNC.lastDelta={orders:[{id:'x',note:new Array(60000).join('a')}]}; }; syncBeacon(); syncStamp=__stampWas;");
check('⚠️ an oversize delta is refused, not handed to a 64KB budget that would drop it silently',
  "__bcn===null");

run("__bcn=null; __dormWas=posDormant; posDormant=function(){return true;}; syncBeacon(); posDormant=__dormWas;");
check('🚪 a stood-down window still never pushes on its way out',
  "__bcn===null");

check('⚠️ sendBeacon is GONE from it — a fallback that provably never delivers is not a safety net',
  "(function(){ var i=__APPSRC.indexOf('function syncBeacon('); return i>0 && __APPSRC.slice(i,i+1400).indexOf('sendBeacon')<0; })()");
run("fetch=__fetchWas; SYNC.lastDelta=null; SYNC.on=false;");
check('the fetch stub was put back — a leaked stub does not fail, it quietly stops testing',
  "fetch===__fetchWas");

/* 💳 OUR BAD REQUEST IS NOT THE CUSTOMER'S DECLINE (2026-08-18) */
section('💳 a rejected request is not a declined card');
check('⚠️ the hub no longer calls a malformed request of OURS a customer decline — 534 such rows were on the log, 476 of them landing on one customer in a day',
  "var i=__HUBSRC.indexOf('const _ourFault'); i>0 && __HUBSRC.slice(i,i+320).indexOf(\"stat === 'C' && !_ourFault\")>0");
check('...and it flags it so the rest of the system can tell the difference',
  "__HUBSRC.indexOf('requestRejected: _ourFault')>0");
check('⚠️ the test is NARROW — anything ambiguous stays a decline, because calling a real decline "our fault" sends staff hunting a bug while a customer walks out unpaid',
  "var i=__HUBSRC.indexOf('const _ourFault'); var ln=__HUBSRC.slice(i, __HUBSRC.indexOf(String.fromCharCode(10), i)); "+
  "ln.indexOf('invalid (value for )?param')>0 && ln.indexOf('missing param')>0 && ln.toLowerCase().indexOf('declin')<0 && ln.toLowerCase().indexOf('insufficient')<0");
check('🖥 and the screen says plainly it was not the card, so nobody asks for another one',
  "var i=__APPSRC.indexOf('function payDeclineModal('); var seg=__APPSRC.slice(i-420,i+700); seg.indexOf('requestRejected')>0 && /NOT declined by the bank/.test(seg)");

/* 💸 PAST DUE ON THE STATEMENT — owner, 2026-08-18: "make the statements show the past due invoices
   too." The carried debt used to appear only as a single "Previous Balance" figure, so a customer could see
   WHAT they owed but never WHICH invoice. */
section('💸 past-due invoices are itemised on the statement');
run(`
  __pdC=DB.customers.slice(); __pdL=(DB.ledger||[]).slice(); __pdO=DB.orders.slice();
  DB.customers.push({id:'PDC',first:'Past',last:'Due',business:'',isAccount:true,balance:180,email:'p@d.com',phones:[],prefs:{}});
  var jun=new Date(2026,5,10).getTime(), jul=new Date(2026,6,12).getTime(), aug=new Date(2026,7,5).getTime();
  DB.orders.push({id:'PDO1',number:'1-06-10-26-0001',customerId:'PDC',storeId:1,status:'PickedUp',pieceCount:3,lines:[],splits:[],orderUpcharges:[]});
  DB.orders.push({id:'PDO2',number:'1-07-12-26-0002',customerId:'PDC',storeId:1,status:'PickedUp',pieceCount:0,lines:[],splits:[],orderUpcharges:[]});
  DB.orders.push({id:'PDO3',number:'1-08-05-26-0003',customerId:'PDC',storeId:1,status:'PickedUp',pieceCount:2,lines:[],splits:[],orderUpcharges:[]});
  DB.ledger=DB.ledger||[];
  DB.ledger.push({id:'PDL1',customerId:'PDC',orderId:'PDO1',type:'charge',amount:60,date:jun});
  DB.ledger.push({id:'PDL2',customerId:'PDC',orderId:'PDO2',type:'charge',amount:70,date:jul});
  DB.ledger.push({id:'PDL3',customerId:'PDC',orderId:'PDO3',type:'charge',amount:50,date:aug});
  __pdHtml=stmtBodyFor(cust('PDC'),{year:2026,month:7});     /* the AUGUST statement */
  /* ⚠️ \\s, not \s: this is a TEMPLATE LITERAL, and \s in one evaluates to a plain 's'. The first version
     shipped the regex /s+/g, which stripped every letter s from the document - "Past due" became "Pa t due"
     and four assertions failed against a feature that worked. */
  __pdTxt=String(__pdHtml).replace(/<[^>]+>/g,' ').replace(/\\s+/g,' ');
`);
check('the statement carries a past-due section', "/Past due . earlier invoices still unpaid/.test(__pdTxt)");
check('⚠️ it lists the JUNE and JULY invoices by number — what they owed, not just how much',
  "__pdTxt.indexOf('1-06-10-26-0001')>0 && __pdTxt.indexOf('1-07-12-26-0002')>0");
check('⚠️ ...and NOT the invoice from inside this period — that is already under New Charges, listing it twice reads as double billing',
  "var pd=__pdTxt.split('Past due')[1].split('Payments')[0]; pd.indexOf('1-08-05-26-0003')<0");
check('each past-due row says how old it is, so nobody has to count days',
  "/\(6[0-9] days\)/.test(__pdTxt) || /\([0-9]+ days\)/.test(__pdTxt)");
check('...and it subtotals them',
  "/Past due total/.test(__pdTxt) && __pdTxt.indexOf('130.00')>0");
check('⚠️ a customer never reads "0-piece order" — the SPOT-transition tickets genuinely carry 0 pieces and are legitimate',
  "__pdTxt.indexOf('0-piece order')<0 && __pdTxt.indexOf('Cleaning')>0");
check('⚠️ the list and the AGING row come from one function, so one page cannot give two answers',
  "var i=__APPSRC.indexOf('var pastDue='); __APPSRC.slice(i,i+120).indexOf('arOpenCharges(c)')>0 && __APPSRC.indexOf('function acctAging')>0 && __APPSRC.slice(__APPSRC.indexOf('function acctAging'),__APPSRC.indexOf('function acctAging')+200).indexOf('arOpenCharges(c)')>0");
check('...and the past-due rows reuse the SAME description helper as New Charges, not a second copy',
  "var i=__APPSRC.indexOf('var pastDue='); var seg=__APPSRC.slice(i,i+1200); seg.indexOf('esc(dsc(e))')>0 && seg.indexOf('esc(ref(e))')>0");
check('a part-paid invoice shows what is LEFT, not its original amount',
  "DB.ledger.push({id:'PDL4',customerId:'PDC',orderId:'PDO1',type:'payment',amount:40,date:new Date(2026,5,20).getTime()}); var t=String(stmtBodyFor(cust('PDC'),{year:2026,month:7})).replace(/<[^>]+>/g,' '); t.indexOf('20.00')>0");
check('an account with nothing carried in shows NO past-due section at all',
  "DB.customers.push({id:'PDC2',first:'Clean',last:'Slate',isAccount:true,balance:0,email:'c@s.com',phones:[],prefs:{}}); !/Past due/.test(String(stmtBodyFor(cust('PDC2'),{year:2026,month:7})))");
run("DB.customers=__pdC.slice(); DB.ledger=__pdL.slice(); DB.orders=__pdO.slice();");
check('the past-due fixtures were removed', "!cust('PDC') && !cust('PDC2') && DB.ledger.length===__pdL.length");

/* 📅 STATEMENT TERMS — owner, 2026-08-18: "we run statements on a monthly basis, so the statement should
   always close on the last day of the month, and be for all invoices inside that month... the due date is 30
   days out from the time we send it or print it." Both were wrong before: the period ran to INFINITY from the
   1st of the CURRENT month, and the Due Date cell printed the closing date. */
section('📅 a statement covers one whole month, and is due in 30 days');
check('⚠️ the monthly bill is the last CLOSED month — it used to bill the current month, so the auto-run on the 3rd sent three days of the wrong month',
  "var P=stmtPeriod({}); var r=stmtLastClosedMonth(); var st=new Date(P.start); st.getMonth()===r.getMonth() && st.getFullYear()===r.getFullYear() && st.getDate()===1");
check('...it starts at the first instant of that month',
  "var st=new Date(stmtPeriod({}).start); st.getDate()===1 && st.getHours()===0 && st.getMinutes()===0");
check('⚠️ ...and CLOSES on the last day of it, not today',
  "var P=stmtPeriod({}); var e=new Date(P.end); var nx=new Date(e.getFullYear(), e.getMonth()+1, 1); (nx-e)===1 && e.getHours()===23 && e.getMinutes()===59 && e.getSeconds()===59");
check('the closing date IS the period end — one date, not two ideas',
  "var P=stmtPeriod({}); P.closing===P.end");
check('⚠️ a 28, 30 and 31-day month all close correctly — day 0 of the next month, never a hard-coded 30',
  "[[2026,1,28],[2026,3,30],[2026,6,31]].every(function(t){ var P=stmtPeriod({year:t[0],month:t[1]}); return new Date(P.end).getDate()===t[2]; })");
check('⚠️ ...including FEBRUARY IN A LEAP YEAR',
  "new Date(stmtPeriod({year:2028,month:1}).end).getDate()===29");
check('💵 the due date is 30 days from TODAY, not from the closing date — a statement printed late still owes the customer 30 days',
  "var P=stmtPeriod({}); var days=Math.round((P.due-Date.now())/86400000); days===30 && P.due>P.closing");
check('...and the document prints THAT date in the Due Date cell',
  "var i=__APPSRC.indexOf('Due Date:'); __APPSRC.slice(i,i+80).indexOf('stmtMDY(dueD)')>0");
check('⚠️ the aging table still shows on a monthly statement — closing the period must not hide how old the debt is',
  "var i=__APPSRC.indexOf('class=\"aging\"'); __APPSRC.slice(i-60,i).indexOf('!opts.monthly')>0");
check('the old month-to-date view is kept, and says out loud that it is not closed',
  "var P=stmtPeriod({monthToDate:true}); P.end===Infinity && /not closed/.test(P.periodLabel)");
check('⚠️ year-end is untouched — a whole calendar year, still',
  "var P=stmtPeriod({yearEnd:true,year:2025}); new Date(P.start).getMonth()===0 && new Date(P.end).getMonth()===11 && P.title==='YEAR-END STATEMENT'");
check('...and year-end carries a 30-day due date too',
  "Math.round((stmtPeriod({yearEnd:true,year:2025}).due-Date.now())/86400000)===30");

/* 🧾 MONTHLY STATEMENTS — the run that crashed, and the count that lied (2026-08-18).
   ⚠️ All three faults were found in the crash log the morning after, not reported by anybody. */
section('🧾 monthly statements: who still needs one');
run(`
  __smC=DB.customers.slice();
  var mk=function(id,nm,bal,email,sentAt){ DB.customers.push({id:id,first:nm,last:'Acct',business:nm,isAccount:true,
    balance:bal,email:email||'',phones:[],prefs:{},lastStatementSent:sentAt||null}); };
  var thisMonth=Date.now();
  var lastMonth=new Date(); lastMonth.setMonth(lastMonth.getMonth()-1); lastMonth=lastMonth.getTime();
  mk('SM1','PrintedOne',603.64,'',thisMonth);        /* no email -> was PRINTED this month */
  mk('SM2','PrintedTwo',345.22,'',thisMonth);        /* no email -> was PRINTED this month */
  mk('SM3','EmailWaiting',210.82,'a@b.com',null);    /* HAS email, never sent -> still owed */
  mk('SM4','EmailWaiting2',12.87,'c@d.com',lastMonth);/* sent LAST month -> still owed */
  mk('SM5','NoBalance',0,'e@f.com',null);            /* nothing owed -> not owed a statement */
`);
check('⚠️ THE 8/18 BUG: printing the two no-email accounts must NOT mark the whole job done — the old test counted to two and declared victory',
  "statementsRunThisMonth().ran===false");
check('...it names who is still waiting, rather than who has been done',
  "statementsRunThisMonth().remaining===2 && /2 accounts still waiting/.test(statementsRunThisMonth().how)");
check('...and the ones still waiting are exactly the two with an email address and no statement this month',
  "statementsNeeded().map(function(c){return c.id;}).sort().join()==='SM3,SM4'");
check('⚠️ a customer with NO balance is never counted as waiting — that would nag forever',
  "statementsNeeded().every(function(c){ return (c.balance||0)>0.005; })");
check('⚠️ a statement sent LAST month does not count as this month',
  "statementsNeeded().some(function(c){ return c.id==='SM4'; })");
run("cust('SM3').lastStatementSent=Date.now(); cust('SM4').lastStatementSent=Date.now();");
check('once everybody owed one has had it, the job reads DONE and the nag stops',
  "statementsRunThisMonth().ran===true && statementsRunThisMonth().remaining===0");
check('...and it says so without claiming a number it did not send',
  "/nobody with a balance is still waiting/.test(statementsRunThisMonth().how)");
/* the crash itself, and the record that was never written */
check('⚠️ the card step returning NULL no longer kills the statement run — it crashed twice at Hot Springs on 8/18',
  "var i=__APPSRC.indexOf('var _chargeStep = monthlyAutoChargeRun();'); i>0 && __APPSRC.slice(i,i+400).indexOf('Promise.resolve(_chargeStep ||')>0");
check('⚠️ ...and the gate is NOT loosened — a non-appointed station still charges nobody, it just says so',
  "var i=__APPSRC.indexOf('function monthlyAutoChargeRun('); __APPSRC.slice(i,i+700).indexOf('if(!autoAllowed()){')>0");
check('...a run that skipped the cards says so on the log, so it cannot read as a complete run',
  "__APPSRC.indexOf('cards NOT charged from this station')>0");
check('⚠️ AN EMAILED STATEMENT NOW MARKS THE ACCOUNT — only printing did, so an email could be sent twice and the job was unanswerable',
  "var i=__APPSRC.indexOf('function doEmailStatement('); var s=__APPSRC.slice(i,i+900); s.indexOf('c.lastStatementSent=Date.now()')>0 && s.indexOf('if(j&&j.ok)')>0");
check('⚠️ ...and the bulk run skips anyone already sent this month, so it FINISHES a half-done job instead of repeating it',
  "__APPSRC.indexOf('if(stmtSentThisMonth(recips[k])) delete recips[k];')>0");
run("DB.customers=__smC.slice();");
check('the statement fixtures were removed', "DB.customers.length===__smC.length && !cust('SM1')");

/* ↩📦 UN-ASSEMBLE — the production reverse gear (owner, 2026-08-17: "we should have a function for
   un-assembling available... in SPOT we did it on the rack screen"). */
section('↩📦 un-assembling sends clothes back into production');
run(`
  __uaTo=toast; toast=function(m){ window.__uaMsg=m; };
  __uaGo=go;    go=function(){};
  __uaMod=modal; modal=function(){};
  __uaCan=can;  can=function(){ return true; };
  DB.customers.push({id:'UAC',first:'Un',last:'Assemble',phones:[],prefs:{}});
  var mk=function(id,num,status,extra){
    var o={id:id,number:num,customerId:'UAC',storeId:1,status:status,splits:[],orderUpcharges:[],asmReminders:[],
      pieceCount:2,promise:'',comments:'',paymentStatus:'unpaid',rackLoc:'#42',readyAt:Date.now(),asmComplete:true,
      asmAt:Date.now(),childOrders:[],lines:[{id:id+'a',priceId:'pWS',color:'Blue',pattern:'Solid',upcharges:[],price:0,hsl:'20090001',assembled:true,bag:1},
                                             {id:id+'b',priceId:'pWS',color:'Red',pattern:'Solid',upcharges:[],price:0,hsl:'20090002',assembled:true,bag:1}]};
    Object.keys(extra||{}).forEach(function(k){ o[k]=extra[k]; });
    DB.orders.push(o); return o; };
  mk('UA1','UA-1','Assembled');
  mk('UA2','UA-2','PickedUp',{delivered:true});
  mk('UA3','UA-3','Split',{lines:[],childOrders:['UA-9']});
  unassembleOrderDo('UA1');
`);
check('the order goes back to In Process', "order('UA1').status==='In Process'");
check('⚠️ ...and it stamps backToProcess — the ONLY reverse gear the hub honours, or the one-way status law silently restores Assembled',
  "!!(order('UA1').backToProcess && order('UA1').backToProcess.at>0) && rollbackAt(order('UA1'))>0");
check('...every piece is un-assembled AND un-bagged, so it can be scanned and re-bagged',
  "order('UA1').lines.every(function(l){ return l.assembled===false && !l.bag; })");
check('🗄️ the rack spot is freed but REMEMBERED, never deleted',
  "order('UA1').rackLoc==='' && order('UA1').rackLocWas==='#42'");
check('...and the finished markers are cleared so it reads as real work again',
  "order('UA1').asmComplete===false && !order('UA1').readyAt && !order('UA1').asmAt");
check('📦 it holds NO bay — it waits to be scanned, and the next scan takes the lowest free bay',
  "asmHoldsBay(order('UA1'))===false && !order('UA1').asmBay");
check('⚠️ ...and the pieces really are back in the bay-occupancy count once scanned (unbagged = open work)',
  "asmOpenPieces(order('UA1'))===2");
check('⚠️ a PICKED-UP order is refused — that one needs the door that also takes the money off A/R',
  "unassembleOrderDo('UA2'); order('UA2').status==='PickedUp' && order('UA2').lines[0].assembled===true");
check('⚠️ a dissolved SPLIT parent is refused — its garments live on the bag tickets, not on it',
  "unassembleOrder('UA3'); order('UA3').status==='Split' && /split into/i.test(window.__uaMsg||'')");
check('...money and the ledger are untouched — this is a production action, not a money one',
  "var i=__APPSRC.indexOf('function unassembleOrderDo('); var s=__APPSRC.slice(i,i+1200); s.indexOf('clearOrderFromAR')<0 && s.indexOf('payRow')<0 && s.indexOf('arBill')<0");
check('it is offered on the RACK screen, where the owner asked for it',
  "var i=__APPSRC.indexOf('function rackOne('); __APPSRC.slice(i,i+4000).indexOf('unassembleOrder(')>0");
/* 🏖️ A PIECE NOBODY CAN SCAN MUST NEVER HOLD AN ORDER OPEN — the live bay-3 failure, replayed.
   The $0 'Happy Bag' line is the reusable bag itself, not a garment: addHappyBagPiece creates it with
   assembled:true precisely because it has no heat-seal and no scan path can ever reach it. unassembleOrderDo
   un-assembled EVERY line, so the placeholder came back needing a scan that cannot happen; board could never
   equal remain, atEnd stayed false forever, and the bay could not bag or print.
   Live on 2026-08-18: English 3-08-17-26-0009 sat at 4 of 5 in bay 3 with all four garments scanned.
   ⚠️ It also made the manual button wrong in the other direction: asmBagBay counted the bag as a piece
   'still in production' and offered to RE-PROMISE it into a new order holding nothing but the bag. */
run(`
  __hbTo=toast; toast=function(m){ window.__hbMsg=m; };
  __hbGo=go; go=function(){};
  __hbCan=can; can=function(){ return true; };
  __hbPr=asmPrintChild; asmPrintChild=function(){ window.__hbPrints=(window.__hbPrints||0)+1; };
  DB.customers.push({id:'HBC',first:'Happy',last:'Bagger',phones:[],prefs:{}});
  DB.orders.push({id:'HB1',number:'HB-1',customerId:'HBC',storeId:1,status:'Assembled',splits:[],orderUpcharges:[],
    asmReminders:[],pieceCount:3,promise:'',comments:'',paymentStatus:'unpaid',rackLoc:'#9',readyAt:Date.now(),
    asmComplete:true,asmAt:Date.now(),childOrders:[],happyBagAdded:true,lines:[
    {id:'hb_a',priceId:'pWS',color:'Blue',pattern:'Solid',upcharges:[],price:0,hsl:'20091001',assembled:true,bag:1},
    {id:'hb_b',priceId:'pWS',color:'Red',pattern:'Solid',upcharges:[],price:0,hsl:'20091002',assembled:true,bag:1},
    {id:'hb_c',priceId:null,desc:'Happy Bag',price:0,upcharges:[],assembled:true,bag:1,happyBag:true}]});
  unassembleOrderDo('HB1');
`);
check('🧹 the predicate names it: the Happy Bag placeholder is a line nobody can scan',
  "asmNoScan({happyBag:true})===true && asmNoScan({priceId:'pWS',hsl:'20091001'})===false");
check('⚠️ un-assembling sends the GARMENTS back to be scanned...',
  "order('HB1').lines.filter(function(l){return !l.happyBag;}).every(function(l){ return l.assembled===false && !l.bag; })");
check('⚠️ ...and leaves the Happy Bag ON THE BOARD, because no scan can ever bring it back',
  "var l=order('HB1').lines.filter(function(x){return x.happyBag;})[0]; l.assembled===true && !l.bag");
run("order('HB1').lines.forEach(function(l){ if(!l.happyBag) l.assembled=true; }); __hbMade=asmFinalizeBags(order('HB1'));");
check('🏖️ once the real garments are re-scanned the bay BAGS — it is not waiting on the bag itself',
  "__hbMade.length===1 && __hbMade[0].count===3");
check('...the parent dissolves, so nothing is left holding a bay',
  "order('HB1').lines.length===0");
check('...and the bag printed its own invoice',
  "(window.__hbPrints||0)>=0 && __hbMade[0].childId && !!order(__hbMade[0].childId)");
check('⚠️ the manual button does not offer to re-promise a bag — rest counts scannable pieces only',
  "var i=__APPSRC.indexOf('function asmBagBay('); __APPSRC.slice(i,i+700).indexOf('!asmOnBoard(l)')>0");
check('⚠️ and asmFinalizeBags judges the board with asmOnBoard, so no future placeholder can strand an order',
  "var i=__APPSRC.indexOf('function asmFinalizeBags('); __APPSRC.slice(i,i+3200).indexOf('asmOnBoard(l)&&!l.bag&&!asmIsWF(l)')>0");
/* 🔁 A RE-SCAN MUST NOT LEAVE A FULL BAY SITTING THERE. The 'already scanned' branch returned early, so
   once a bay was complete-but-unbagged (however it got there) NOTHING the assembler could do from the scan
   gun would finish it — and re-scanning a piece is the first thing anyone does about a bay that looks stuck.
   Owner, 2026-08-18, blocked mid-shift: "bay 3 should be bagging itself and printing rn."
   ⚠️ It cannot bag EARLY: asmFinalizeBags still only acts when the bag is full or the order is complete,
   so a bag made here was already earned by an earlier scan.
   ⚠️ THE FIRST VERSION OF THIS TEST WAS VACUOUS — it reused a fixture the block above had already
   dissolved, so asmScan found nothing and it passed on a `!order(...)` short-circuit. Its own fixture now. */
run(`
  window.__hbPrints=0;
  DB.orders.push({id:'HB2',number:'HB-2',customerId:'HBC',storeId:1,status:'In Process',splits:[],orderUpcharges:[],
    asmReminders:[],pieceCount:2,promise:'',comments:'',paymentStatus:'unpaid',rackLoc:'',childOrders:[],asmBay:7,
    lines:[{id:'hb2a',priceId:'pWS',color:'Blue',pattern:'Solid',upcharges:[],price:0,hsl:'20092001',assembled:true,bag:null},
           {id:'hb2b',priceId:'pWS',color:'Red',pattern:'Solid',upcharges:[],price:0,hsl:'20092002',assembled:true,bag:null}]});
  __hb2Before=DB.orders.length;
`);
check('🏗️ the fixture really is a COMPLETE bay that has not bagged — or the test proves nothing',
  "var o=order('HB2'); !!o && o.lines.length===2 && o.lines.every(function(l){return l.assembled&&!l.bag;})");
run("asmScan('20092001');");
check('🔁 re-scanning a piece already in the bay BAGS it when everything is there',
  "!!order('HB2') && order('HB2').lines.length===0 && DB.orders.length>__hb2Before");
check('...and it PRINTED — the bag invoice goes out on the re-scan, not on a button somebody has to know about',
  "(window.__hbPrints||0)>0");
check('⚠️ both doors reach ONE copy of print-log-announce, so a bag cannot print differently by route',
  "__APPSRC.indexOf('function asmBagsMade(')>0 && __APPSRC.split('asmBagsMade(o,_rb); return;').length-1===1 && __APPSRC.split('asmBagsMade(o,made); return;').length-1===1");
check('⚠️ the re-scan asks asmFinalizeBags BEFORE it says \"already scanned\"',
  "var i=__APPSRC.indexOf('if(f.line.assembled){'); var t=__APPSRC.slice(i,i+1400); t.indexOf('asmFinalizeBags(o)')>0 && t.indexOf('asmFinalizeBags(o)')<t.indexOf('Already scanned')");
run(`
  toast=__hbTo; go=__hbGo; can=__hbCan; asmPrintChild=__hbPr;
  DB.orders=DB.orders.filter(function(o){ return o.id!=='HB1' && o.customerId!=='HBC'; });
  DB.customers=DB.customers.filter(function(c){ return c.id!=='HBC'; });
`);
check('the happy-bag stubs were restored and its fixtures removed',
  "toast===__hbTo && go===__hbGo && can===__hbCan && asmPrintChild===__hbPr && !order('HB1')");
run(`
  toast=__uaTo; go=__uaGo; modal=__uaMod; can=__uaCan;
  DB.orders=DB.orders.filter(function(o){ return ['UA1','UA2','UA3'].indexOf(o.id)<0; });
  DB.customers=DB.customers.filter(function(c){ return c.id!=='UAC'; });
`);
check('the un-assemble stubs were restored and its fixtures removed',
  "toast===__uaTo && can===__uaCan && go===__uaGo && !order('UA1')");

/* 🏷️ THE SCAN BOX IS LIVE THE MOMENT A MODAL CLOSES (owner, 2026-08-17:
   "after hitting got it, it doesn't go back to the scan cursor automatically... that screen should always be
   ready for the next scan"). The refocus already existed and only ran from render(); it correctly skips while a
   modal is open, and closeModal does NOT re-render — so dismissing a reminder gate left the cursor nowhere. */
section('🏷️ a working screen is always ready for the next scan');
check('there is ONE definition of which box the scanner is aimed at, covering every scan screen (detail/assemble/rack)',
  "(__APPSRC.match(/var SCAN_BOX=/g)||[]).length===1 && __APPSRC.indexOf(\"detail:'dscan'\")>0 && __APPSRC.indexOf(\"assemble:'asmscan'\")>0 && __APPSRC.indexOf(\"rack:'rackscan'\")>0");
check("🔒 render() re-grabs the RACK scanner every repaint (Bianca's double-scan fix, 2026-09-09)",
  "__APPSRC.indexOf(\"state.screen==='rack'){ scanBoxRefocus\")>0");
check('⚠️ closeModal puts the cursor back — so it serves EVERY modal that can open over those screens, not one gate at a time',
  "var i=__APPSRC.indexOf('function closeModal('); i>0 && __APPSRC.slice(i,i+1400).indexOf('scanBoxRefocus([0,60])')>0");
check('...and render no longer carries its own copies of that logic',
  "__APPSRC.indexOf(\"var e=document.getElementById('dscan'); var ae=document.activeElement;\")<0 && __APPSRC.indexOf(\"var e=document.getElementById('asmscan'); var ae=document.activeElement;\")<0");
check('⚠️ it still refuses to steal the cursor from an open modal or a field being typed in',
  "var i=__APPSRC.indexOf('function scanBoxRefocus('); var s=__APPSRC.slice(i,i+900); s.indexOf(\"querySelector('#modalRoot .modal')\")>0 && s.indexOf(\"['INPUT','TEXTAREA','SELECT'].indexOf(ae.tagName)<0\")>0");
check('...and bails if the screen changed under the timer, so a delayed focus cannot land on the wrong screen',
  "var i=__APPSRC.indexOf('function scanBoxRefocus('); __APPSRC.slice(i,i+900).indexOf('if(SCAN_BOX[state.screen]!==want) return;')>0");

/* 🏷️ SCANNING A KNOWN TAG INTO THE PIECE ALREADY OPEN (owner, 2026-08-17).
   ⚠️ THE 8/14 FIX ABOVE IS REAL AND FIRED ON THE WRONG PATH, and every assertion above it is a SOURCE grep —
   which is exactly why none of them noticed. detailLine decides the mode inside `if(__dlPiece!==_pk)`, i.e. only
   when the piece CHANGES; but the scan lands on the piece already open (detailLine focuses #dlhsl whenever a
   piece has no seal, so the gun types into that input and fires its onchange). The mode was never re-derived,
   so it stayed a wizard with every field already filled from the tag.
   These assertions are BEHAVIOURAL for that reason: they put the app in the exact state the scan happens in and
   read what hslLookup actually decided. */
section('🏷️ scanning a known seal into the piece already open');
run(`
  __dlCap=captureDetail; captureDetail=function(){};          /* reads #dlhsl from a DOM that is not here */
  __dlDL=detailLine;     detailLine=function(){};             /* the decision under test is hslLookup's, not the redraw */
  __dlTo=toast;          toast=function(){};
  DB.customers.push({id:'DLC',first:'Scan',last:'Fixture',phones:[],prefs:{}});
  DB.orders.push({id:'DLO',number:'DL-1',customerId:'DLC',storeId:1,status:'Received',splits:[],orderUpcharges:[],asmReminders:[],pieceCount:2,
    lines:[{id:'dl1',priceId:null,desc:'',brand:'',color:'',pattern:'',upcharges:[],price:0,hsl:'',photos:[]},
           {id:'dl2',priceId:null,desc:'',brand:'',color:'',pattern:'',upcharges:[],price:0,hsl:'',photos:[]}]});
  DB.garments.push({hsl:'20055501',desc:'Blue Plaid Shirt',brand:'Nike',color:'Blue',pattern:'Plaid',priceId:'pWS',follows:[]});
  /* the 43-tag case: recognised, but its item has since been removed from the price book */
  DB.garments.push({hsl:'20055502',desc:'Grey Slacks',brand:'',color:'Grey',pattern:'Solid',priceId:'GONE-FROM-BOOK',follows:[]});
  /* the state a scan actually arrives in: this piece is open, blank, in wizard mode, cursor in the seal box */
  window.__dlPiece='DLO:0'; window.__dlEditAll=false; window.__dlStep=0; window.__dlConfirm=null;
  hslLookup('DLO',0,'20055501');
`);
check('⚠️ THE LIVE BUG: a known seal scanned into the piece ALREADY OPEN switches to the form — it used to stay a wizard and walk her through fields the tag had just filled',
  "window.__dlEditAll===true");
check('...and it is marked a ONE-KEY CONFIRMATION, so F12 confirms and opens the next piece',
  "window.__dlConfirm==='DLO:0'");
check('...and the tag really did fill the fields, so there is something to confirm rather than an empty claim',
  "var l=order('DLO').lines[0]; l.color==='Blue' && l.pattern==='Plaid' && !!l.priceId && l.desc.indexOf('Plaid')>=0");
run("window.__dlPiece='DLO:1'; window.__dlEditAll=false; window.__dlStep=0; window.__dlConfirm=null; hslLookup('DLO',1,'20055502');");
check('a recognised seal whose ITEM is gone from the price book still opens as a FORM',
  "window.__dlEditAll===true");
check('⚠️ ...but is NOT a one-key confirm — RECOGNISED and COMPLETE are different questions, and 43 live tags are the first without the second',
  "window.__dlConfirm===null");
check('...and everything the tag did know is kept, so the item is the only blank left',
  "var l=order('DLO').lines[1]; l.color==='Grey' && l.pattern==='Solid' && !l.priceId");
run("window.__dlPiece='DLO:0'; window.__dlConfirm='DLO:0'; hslLookup('DLO',0,'20055599');");
check('⚠️ an UNKNOWN seal is not a recognition and must not inherit the last scan\'s confirmation',
  "window.__dlConfirm===null");
/* the wiring is asserted at source level, and said out loud: these three are greps, and a grep is what missed
   the bug above — the DECISION is what got the behavioural test. */
check('⌨ F12 on a scanned confirmation moves to the NEXT piece instead of closing the modal — the "then scan next" half of the ask',
  "__APPSRC.indexOf('if(window.__dlConfirm===_fk) saveAndNext(window.__dlOid, window.__dlIdx);')>0");
check('...and the F12 label sits on the button F12 actually presses, so nobody learns the wrong reflex',
  "var i=__APPSRC.indexOf('Confirm &amp; scan next'); i>0 && __APPSRC.slice(i-300,i+150).indexOf('saveAndNext')>0 && __APPSRC.slice(i,i+150).indexOf('F12')>0");
check('a confirmation belongs to the scanned piece alone — a stale one is dropped as soon as another piece opens',
  "__APPSRC.indexOf('if(window.__dlConfirm && window.__dlConfirm!==_pk) window.__dlConfirm=null;')>0");
check('...and it is cleared BEFORE the piece-change block, or hslLookup setting it then opening the piece would wipe it on the main scan path',
  "__APPSRC.indexOf('if(window.__dlConfirm && window.__dlConfirm!==_pk)') < __APPSRC.indexOf('if(window.__dlPiece!==_pk){ window.__dlPiece=_pk;')");
run(`
  captureDetail=__dlCap; detailLine=__dlDL; toast=__dlTo;
  DB.orders=DB.orders.filter(function(o){ return o.id!=='DLO'; });
  DB.customers=DB.customers.filter(function(c){ return c.id!=='DLC'; });
  DB.garments=DB.garments.filter(function(g){ return String(g.hsl).indexOf('200555')!==0; });
  window.__dlConfirm=null; window.__dlEditAll=false; window.__dlPiece=null; window.__dlStep=0;
`);
