check('📞 a YES from the SECOND phone on the record puts that customer on the route too (the Hallams, 9/22: the other spouse answered)', "(DB.customers.find(function(x){return x.id==='RH2';})||{}).needsPickup===true");
run(`fetch=__r2.fetch; SYNC.on=__r2.on; SYNC.apiBase=__r2.api; SYNC.status=__r2.st; SYNC.autoLeader=__r2.ld; if(__r2.key==null) localStorage.removeItem('ozarkpos_huk'); else localStorage.setItem('ozarkpos_huk',__r2.key); custNotify=__r2.cn; DB.customers=DB.customers.filter(function(c){ return c.id!=='RH2'; });`);
