check('🚐 the section renders with a Confirm-all and per-line Confirm', "var h=routeAutoAddsHtml(); h.indexOf('HS Delivery')>0 && h.indexOf('routeAutoAckAll()')>0 && h.indexOf(\"routeAutoAck('AA1')\")>0");
