section('— 📅 Arkadelphia is closed Wednesdays (and weekends) —');
run("window.__wed=(function(){var w=new Date();w.setDate(w.getDate()+14);while(w.getDay()!==3)w.setDate(w.getDate()+1);return isoLocal(w);})(); window.__sat=(function(){var s=new Date();s.setDate(s.getDate()+14);while(s.getDay()!==6)s.setDate(s.getDate()+1);return isoLocal(s);})(); window.__sun=(function(){var u=new Date();u.setDate(u.getDate()+14);while(u.getDay()!==0)u.setDate(u.getDate()+1);return isoLocal(u);})();");
check('📅 the plant (store 1) is CLOSED on a Wednesday — a promise there is named, not silently allowed', "String(promiseClosedName(window.__wed,1)).indexOf('Wednesday')>=0");
check('📅 ...and on a Saturday too — the plant runs Mon/Tue/Thu/Fri', "!!promiseClosedName(window.__sat,1)");
check('📅 Hot Springs (store 2) is OPEN Wed and Sat but CLOSED Sunday — each store its own week', "promiseClosedName(window.__wed,2)==='' && promiseClosedName(window.__sat,2)==='' && !!promiseClosedName(window.__sun,2)");
check('📅 a plant promise rolls OFF a Wednesday onto an open day (never Sun/Wed/Sat)', "var o=promiseOpenISO(window.__wed,1); [0,3,6].indexOf(new Date(o+'T12:00:00').getDay())<0");
check('📅 the plant DEFAULT promise never lands on Wed/Sat/Sun', "var o=promiseDefault(1); [0,3,6].indexOf(new Date(o+'T12:00:00').getDay())<0");
check('📅 a Hot Springs promise never lands on a Sunday', "var o=promiseDefault(2); new Date(o+'T12:00:00').getDay()!==0 && promiseOpenISO(window.__sun,2)!==window.__sun");
check('📅 ...and it is store-aware: an undefined store keeps the old holiday-only behavior (backward compatible)', "typeof promiseDefault()==='string' && promiseDefault().length===10");
run("delete window.__wed; delete window.__sat; delete window.__sun;");

/* ───────────── ⛔📅 NEVER a past promise (owner 2026-09-09) ─────────────
   Two Hot Springs orders were hand-typed a promise date in the PAST (created 9/8, promised 9/4). The
   promise calcs all produce FUTURE dates, so this only happens when a human types a past day into the
   date box. Every hand-typed door now floors the date at today before the closed/route snaps run —
   a past promise rolls forward to the store's default open day instead of quietly landing overdue. */
section('— ⛔📅 a hand-typed past promise date rolls forward, never lands overdue —');
run("window.__past=isoLocal(new Date(Date.now()-3*86400000));");   // 3 days ago
run("DB.orders.push({id:'PASTDET',number:'X-PAST-1',customerId:null,storeId:1,status:'Detailed',kind:'press',pieceCount:1,promise:'2026-12-01',lines:[{id:'pl1'}]});");
run("(function(){ var g=go,t=toast,c=closeModal; go=function(){};toast=function(){};closeModal=function(){}; setDetailPromise('PASTDET',window.__past); go=g;toast=t;closeModal=c; })();");
check('📅 setDetailPromise floors a past date forward to today or later', "var o=DB.orders.find(function(x){return x.id==='PASTDET';}); o.promise>=todayISO()");
check('📅 ...and it stamped the change (Ike Bakewell rule)', "var o=DB.orders.find(function(x){return x.id==='PASTDET';}); o._t>1e15");
run("DB.orders.push({id:'PASTASM',number:'X-PAST-2',customerId:null,storeId:1,status:'Assembled',kind:'press',pieceCount:1,asmFound:0,promise:'2026-12-01',lines:[{id:'al1'}]});");
run("(function(){ var g=go,t=toast; go=function(){};toast=function(){}; asmRepromise('PASTASM',window.__past); go=g;toast=t; })();");
check('📅 asmRepromise floors a past date forward too', "var o=DB.orders.find(function(x){return x.id==='PASTASM';}); o.promise>=todayISO()");
check('📅 all three hand-typed doors floor at today (createOrder, setDetailPromise, asmRepromise)',
  "(function(){ var n=(__APPSRC.match(/if\\(promise < todayISO\\(\\)\\)|if\\(nd < todayISO\\(\\)\\)|if\\(v < todayISO\\(\\)\\)/g)||[]).length; return n===3; })()");
run("DB.orders=DB.orders.filter(function(o){return o.id!=='PASTDET'&&o.id!=='PASTASM';}); delete window.__past;");

section('— 🕰 pre-9/1 timeclock is archived: no owner flag, no employee sign-off —');
run("window.__taWas=DB.timeAcks; DB.timeAcks=[]; window.__eidWas=state.employeeId; state.employeeId='OWNERX';");
check('🕰 a time change to a PRE-launch punch queues NO employee sign-off', "addTimeAck('E1','edit','a','b',{id:'OWNERX',name:'Owner'},{inWas:TC_EPOCH-86400000,inNow:TC_EPOCH-86400000,outWas:TC_EPOCH-80000000,outNow:TC_EPOCH-80000000}); DB.timeAcks.length===0");
check('🕰 a time change to a POST-launch punch DOES queue a sign-off', "addTimeAck('E1','edit','a','b',{id:'OWNERX',name:'Owner'},{inWas:TC_EPOCH+86400000,inNow:TC_EPOCH+86400000}); DB.timeAcks.length===1");
check('🕰 pendingTimeAcks hides a pre-launch ack even if one is on record', "DB.timeAcks.push({id:'z',empId:'E1',ackedAt:null,inNow:TC_EPOCH-1000}); pendingTimeAcks('E1').length===1");
check('🕰 an archived pre-launch open punch never trips the >24h owner alarm', "isStaleOpen({in:TC_EPOCH-10*86400000})===false && isStaleOpen({in:Date.now()-25*3600000})===true");
run("DB.timeAcks=window.__taWas; delete window.__taWas; state.employeeId=window.__eidWas; delete window.__eidWas;");

section('— ✍️⛔ starting the day (tile+PIN) forces a pending sign-off, not only the Hub punch —');
run([
  "window.__dl={ge:go, sv:saveSession, tg:timeAckGate, cm:closeModal, vl:val, eid:state.employeeId, rd:(typeof registerDevice==='function'?registerDevice:null)};",
  "DB.employees.push({id:'DLE',name:'Login Tester',role:'staff',pin:'7654',active:true,rate:0}); DB.timeAcks=DB.timeAcks||[];",
  "window.__gate=null; go=function(){}; saveSession=function(){}; closeModal=function(){}; if(window.__dl.rd) registerDevice=function(){}; timeAckGate=function(id){ window.__gate=id; }; val=function(x){ return x==='pin'?'7654':window.__dl.vl(x); }; state.employeeId=null;",
  "addTimeAck('DLE','edit','a','b',{id:'OWNERX',name:'Owner'},{inWas:TC_EPOCH+3600000,inNow:TC_EPOCH+3600000}); doLogin('quick');"
].join(''));
check('✍️⛔ a pending change GATES the tile+PIN login — the sign-off fires, operator is NOT set', "window.__gate==='DLE' && state.employeeId===null");
run("DB.timeAcks=DB.timeAcks.filter(function(a){return a.empId!=='DLE';}); window.__gate=null; doLogin('quick');");
check('✍️⛔ with nothing pending, the same login proceeds normally (operator set, no gate)', "window.__gate===null && state.employeeId==='DLE'");
run([
  "go=window.__dl.ge; saveSession=window.__dl.sv; timeAckGate=window.__dl.tg; closeModal=window.__dl.cm; val=window.__dl.vl; if(window.__dl.rd) registerDevice=window.__dl.rd; state.employeeId=window.__dl.eid;",
  "DB.employees=DB.employees.filter(function(e){return e.id!=='DLE';}); DB.timeAcks=DB.timeAcks.filter(function(a){return a.empId!=='DLE';}); delete window.__dl; delete window.__gate;"
].join(''));

section('— 🔒 customer reservation: the second computer waits —');
run("DB.customers.push({id:'RESVC1',first:'Test',last:'Reserve',_t:hlcNow()}); DB.orders.push({id:'RESVO1',number:'Z-1',customerId:'RESVC1',status:'Detailed',lines:[],_t:hlcNow()});");
check('🔒 go() drives the reservation on every real navigation', "String(go).indexOf('resvReconcile(')>0");
check('🔒 the WAIT panel is wired to draw IN PLACE of the transaction screen', "__APPSRC.indexOf('_resvGate')>0 && __APPSRC.indexOf('resvGateHtml()')>0");
check('🔒 a non-transaction screen holds nobody', "screenCust('home',{})===null && screenCust('admin',{})===null");
check('🔒 pickup / quickform / routeConfirm / arcollect each resolve their own customer', "screenCust('pickup',{customerId:'CX'})==='CX' && screenCust('quickform',{cid:'CY'})==='CY' && screenCust('routeConfirm',{cid:'CZ'})==='CZ' && screenCust('arcollect',{cid:'CW'})==='CW'");
check('🔒 detail resolves the customer through its order', "screenCust('detail',{orderId:'RESVO1'})==='RESVC1'");
run("window.__resvSaved={on:SYNC.on,api:SYNC.apiBase}; SYNC.on=false;");
check('🔒 FAIL-OPEN: with no hub a take resolves to mine:true synchronously — a counter is NEVER frozen by the reserve', "var got=null; resvPost('CX','take',function(j){got=j;}); !!got && got.mine===true");
check('🔒 FAIL-OPEN: resvOn() is false when the hub is down', "resvOn()===false");
run("SYNC.on=window.__resvSaved.on; SYNC.apiBase=window.__resvSaved.api; delete window.__resvSaved;");
run("window.__resv={cid:'RESVC1',state:'blocked',by:'Hot Springs Counter'}; state.screen='pickup'; state.params={customerId:'RESVC1'};");
check('🔒 the WAIT panel names who to wait on and says to wait', "var h=resvGateHtml(); h.indexOf('in use')>0 && h.indexOf('Hot Springs Counter')>0 && h.indexOf('wait')>0");
check('🔒 the WAIT panel is EMPTY for a screen whose customer is not the held one', "state.params={customerId:'OTHER'}; resvGateHtml()===''");
run("state.params={customerId:'RESVC1'}; window.__resv={cid:'RESVC1',state:'mine'};");
check('🔒 no WAIT panel when the hold is MINE', "resvGateHtml()===''");
check('🔒 leaving hands off through resvLeave (push → confirm → release), not a bare release', "String(resvReconcile).indexOf('resvLeave(')>0");
check('🔒 resvLeave fires the delta only when pending, archives it, and starts the confirm wait', "var s=String(resvLeave); s.indexOf('SYNC.localDirty')>0 && s.indexOf('syncPush()')>0 && s.indexOf('trailAdd(')>0 && s.indexOf('resvConfirmRelease(')>0");
run("window.__resvPostWas=resvPost; window.__syncSave={d:SYNC.localDirty,s:SYNC.status,p:SYNC.pushing}; resvPost=function(cid,action,cb){ if(action==='release') window.__resvRel=cid; if(cb) cb({ok:true,mine:true}); };");
run("window.__resvRel=null; window.__resvDrain={}; window.__resvDrain['DC1']={at:Date.now()}; SYNC.localDirty=false; SYNC.status='ok'; SYNC.pushing=false; resvConfirmRelease('DC1');");
check('🔒 CONFIRM: once the hub has our delta (sync idle + healthy), the hold releases', "window.__resvRel==='DC1' && !(window.__resvDrain&&window.__resvDrain['DC1'])");
run("window.__resvRel=null; window.__resvDrain={}; window.__resvDrain['DC2']={at:Date.now()}; SYNC.localDirty=true; SYNC.status='ok'; SYNC.pushing=false; resvConfirmRelease('DC2');");
check('🔒 WAIT: while the delta is still unconfirmed, the customer is HELD, never released (owner: I will take the wait)', "window.__resvRel===null && !!(window.__resvDrain&&window.__resvDrain['DC2'])");
check('🔒 the wait is BOUNDED so a slow/offline hub can never freeze the handoff', "String(resvConfirmRelease).indexOf('15000')>0");
run("SYNC.localDirty=window.__syncSave.d; SYNC.status=window.__syncSave.s; SYNC.pushing=window.__syncSave.p; resvPost=window.__resvPostWas; window.__resvDrain={}; delete window.__resvPostWas; delete window.__resvRel; delete window.__syncSave;");
run("window.__resv=null; state.screen='home'; state.params={}; DB.orders=DB.orders.filter(function(o){return o.id!=='RESVO1';}); DB.customers=DB.customers.filter(function(c){return c.id!=='RESVC1';});   /* a test that leaves data behind breaks the next one */");

section('— 🏖 vacation-used rides the EMPLOYEE record, so it reaches every station —');
/* DB.payVac was a synced collection in name only — the hub never stored it, deltas refuse it as an unknown
   key, the pull merge never read it — so hours typed at one station existed ONLY there, and the year-end
   payout (unused balance at 1.5x) would silently overpay from any other station. Moved onto e.vacUsed
   2026-09-08; the old map stays as a read fallback, retired one key at a time. */
run("__vacCanWas=can; can=function(){ return true; }; __vacGoWas=go; go=function(){}; __vacToastWas=toast; toast=function(){};");
run("DB.employees.push({id:'VACE1',name:'Vac Test',rate:12,vacAnnual:40,_t:1});");
run("setVacUsed('VACE1', new Date(2026,7,20).getTime(), '16');");
check('🏖 the hours land ON the employee record, keyed by the pay period', "(function(){ var e=DB.employees.find(function(x){return x.id==='VACE1';}); return !!e.vacUsed && e.vacUsed[String(new Date(2026,7,16).getTime())]===16; })()");
check('...and the employee was STAMPED — an unstamped content edit loses the pull-race tie (Ike Bakewell, 8/21)', "DB.employees.find(function(x){return x.id==='VACE1';})._t>1e15");
check('...and the payroll edit is on the activity log', "DB.activity.some(function(a){return a.type==='PAYROLL EDIT' && String(a.detail||'').indexOf('Vac Test')>=0;})");
check('vacUsedHrs answers from the record', "vacUsedHrs('VACE1', payPeriodOf(new Date(2026,7,20).getTime()))===16");
check('vacBalance = annual minus used YTD', "vacBalance('VACE1', new Date(2026,10,1).getTime())===24");
run("DB.payVac=DB.payVac||{}; DB.payVac['VACE1|'+new Date(2026,6,16).getTime()]=8;");
check('a legacy payVac entry still counts (read fallback, never a wipe — the never-delete rule)', "vacUsedYTD('VACE1', new Date(2026,10,1).getTime())===24");
check('...and reads for its own period', "vacUsedHrs('VACE1', payPeriodOf(new Date(2026,6,20).getTime()))===8");
run("var __ve=DB.employees.find(function(x){return x.id==='VACE1';}); __ve.vacUsed=__ve.vacUsed||{}; __ve.vacUsed[String(new Date(2026,6,16).getTime())]=8;   /* defensive so a regression fails the CHECKS below, not the harness */");
check('⚠️ a period present in BOTH homes is counted once, never doubled', "vacUsedYTD('VACE1', new Date(2026,10,1).getTime())===24");
run("setVacUsed('VACE1', new Date(2026,6,20).getTime(), '8');");
check('rewriting a period through setVacUsed retires its legacy key', "DB.payVac['VACE1|'+new Date(2026,6,16).getTime()]===undefined");
check('year-end payout is what is left: 40 minus 24 = 16h', "vacPayout('VACE1', payPeriodOf(new Date(2026,11,20).getTime()))===16");
/* 🚐 store 3 is the route — owner, 2026-09-08: "it doesn't have a drawer" */
