section('— 📆 push a straggler to next Wednesday from the loading board —');
run(`
  DB.customers.push({id:'RPW1', first:'Push', last:'Week', route:'Hot Springs Route', stop:9, phone:'5015550012', _t:hlcNow()});
  DB.orders.push({id:'RPWO1', number:'P-1', customerId:'RPW1', storeId:3, status:'Ready', fulfill:'route', route:'Hot Springs Route', pieceCount:2, createdAt:Date.now(), promise:'2026-09-09', lines:[{id:'rl1',priceId:'x'},{id:'rl2',priceId:'x'}], orderUpcharges:[], _t:hlcNow()});
  __rpwGoWas=go; window.__rpwWent=null; go=function(s,p){ window.__rpwWent=s; }; __rpwToastWas=toast; toast=function(){}; __rpwCMWas=closeModal; closeModal=function(){};
  state.screen='driver'; state.params={route:'Hot Springs Route'};
  window.__rpwWed=routeWeds(1)[0];   /* the upcoming Wednesday — a hardcoded date expires and the app rightly refuses a past promise */
  setDetailPromise('RPWO1',window.__rpwWed,1);
  go=__rpwGoWas; toast=__rpwToastWas; closeModal=__rpwCMWas;
`);
check('📆 the stay flag lands BACK on the screen she was loading from, never Detail', "window.__rpwWent==='driver'");
check('📆 ...the promise moved to the picked Wednesday, stamped (Ike Bakewell rule)', "var o=DB.orders.find(function(x){return x.id==='RPWO1';}); o.promise===window.__rpwWed && o._t>1e15");
check('📆 ...and the change is on the activity log', "DB.activity.some(function(a){return a.type==='Promise changed' && String(a.detail||'').indexOf('P-1')>=0;})");
check('📆 the not-racked loading list offers the push door on every row', "String(notRackedDueHTML).indexOf('routePushWeek')>0");
/* RETARGETED 2026-09-22 — a TIME BOMB: it picked the fixed Tuesday 2026-09-22 and expected 9/23, so from 9/23 on the
   pick was in the past, the app (rightly) refused it, and the gate failed on every build — it would have blocked the
   9/23 route-day deploy. It now picks a Tuesday at least a week out and asks for the Wednesday after it. */
check('📆 the chips still snap a route order to WEDNESDAYS (a Tuesday pick becomes Wed)', "(function(){ var o=DB.orders.find(function(x){return x.id==='RPWO1';}); var g2=go; go=function(){}; var t2=toast; toast=function(){}; var c2=closeModal; closeModal=function(){}; var iso=function(x){ return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0'); }; var d=new Date(todayISO()+'T12:00:00'); d.setDate(d.getDate()+8); while(d.getDay()!==2) d.setDate(d.getDate()+1); var tue=iso(d); setDetailPromise('RPWO1',tue,1); go=g2; toast=t2; closeModal=c2; var p=new Date(o.promise+'T12:00:00'); return p.getDay()===3 && o.promise>tue && (p-d)<8*86400000; })()");
run("DB.orders=DB.orders.filter(function(o){return o.id!=='RPWO1';}); DB.customers=DB.customers.filter(function(c){return c.id!=='RPW1';}); DB.activity=DB.activity.filter(function(a){return String(a.detail||'').indexOf('P-1')<0;}); state.screen='home'; state.params={}; delete window.__rpwWent;");

section('— 📜 a split bag’s history shows who took it in (the parent’s Quick) —');
run(`
  __ohWas=DB.activity;
  DB.activity=[
    {ts:1000, emp:'Eleanor Bowden', ws:'Hot Springs Counter', type:'Quick', detail:'2-09-04-26-0024 (1pc)'},
    {ts:2000, emp:'Blake Sandiford', ws:'Assembly', type:'Detail', detail:'2-09-04-26-0024-01'},
    {ts:3000, emp:'Blake Sandiford', ws:'Assembly', type:'Bag → own invoice', detail:'2-09-04-26-0024-01 (1 pc) split off 2-09-04-26-0024'},
    {ts:4000, emp:'Nobody', ws:'X', type:'Quick', detail:'9-99-99-99-9999 (unrelated)'}
  ];
  window.__disc=window.__disc||{}; window.__disc['ohist:2-09-04-26-0024-01']=true;
  __ohHtml=orderHistoryHtml({number:'2-09-04-26-0024-01', splitFrom:'2-09-04-26-0024', status:'Assembled', lines:[{priceId:'x'}]});
  DB.activity=__ohWas;
`);
