check('📜 ...and the Detail attribution shows too', "__ohHtml.indexOf('Blake Sandiford')>=0 && __ohHtml.indexOf('Detail')>=0");
check('📜 ...but an UNRELATED order’s event is not pulled in', "__ohHtml.indexOf('9-99-99-99-9999')<0");
check('📜 the base order number is derived from splitFrom, else the -NN suffix is stripped', "(function(){ var i=__APPSRC.indexOf('function orderHistoryHtml'); var seg=__APPSRC.slice(i,i+900); return seg.indexOf('o.splitFrom')>0 && /\\(\\.\\*\\\\d\\)-\\\\d\\{2\\}/.test(seg); })()");
check('📜 the full-record pull hits the hub archive by base order number (never trimmed)', "(function(){ var i=__APPSRC.indexOf('function orderHistoryLoad'); var seg=__APPSRC.slice(i,i+700); return seg.indexOf('/api/activity?q=')>0 && seg.indexOf('encodeURIComponent(base)')>0; })()");
check('📜 the history panel AUTO-pulls the chunk when open + connected — no manual button (owner: history = the activity log filtered by order)', "(function(){ var i=__APPSRC.indexOf('function orderHistoryHtml'); var seg=__APPSRC.slice(i,i+1700); return seg.indexOf('orderHistoryLoad(base, o)')>0 && seg.indexOf('ohbody-')>0; })()");
check('📜 ...and it refreshes only when the cached chunk is stale, so the 4s repaint does not hammer the hub', "(function(){ var i=__APPSRC.indexOf('function orderHistoryHtml'); var seg=__APPSRC.slice(i,i+1700); return /Date\\.now\\(\\)-\\(cache\\.at\\|\\|0\\)\\)>12000/.test(seg); })()");
check('📜 a second station holding the same open panel does not fire a duplicate fetch (in-flight guard)', "(function(){ var i=__APPSRC.indexOf('function orderHistoryLoad'); var seg=__APPSRC.slice(i,i+400); return seg.indexOf('if(window.__ohLoading[base]) return;')>0; })()");
check('📜 the device activity window is ONE tunable constant (ACT_CAP), not a magic number in three places (owner 2026-09-10: ~7 weeks)', "typeof ACT_CAP==='number' && ACT_CAP>=10000 && String(syncMergeAct).indexOf('ACT_CAP')>0 && String(logEvent).indexOf('ACT_CAP')>0");

section('— 🏷️ the detailing wizard puts Wet Press first —');
check('🏷️ svCatOrder moves Wet Press to the front, right after All (owner 2026-09-10)', "JSON.stringify(svCatOrder(['Dry Press Tops','Dry Press Bottoms','Wet Press','Misc']))===JSON.stringify(['Wet Press','Dry Press Tops','Dry Press Bottoms','Misc'])");
check('🏷️ ...case/space tolerant, and a no-wet-press list is untouched', "JSON.stringify(svCatOrder(['A','wetpress','B']))===JSON.stringify(['wetpress','A','B']) && JSON.stringify(svCatOrder(['A','B']))===JSON.stringify(['A','B'])");
check('🏷️ the detail picker chips render through svCatOrder (the item grid stays price-book order)', "(function(){ var i=__APPSRC.indexOf('let svChips='); return __APPSRC.slice(i,i+200).indexOf('svCatOrder(Object.keys(byCat))')>0; })()");

section('— 🧮 the quote pad clears itself on the way out —');
run(`
  __qcToastWas=toast; window.__qcToasts=[]; toast=function(t){ window.__qcToasts.push(String(t||'')); };
  state.screen='quote'; state.quoteLines=[{priceId:'p1',qty:3,upcharges:[]}];
  go('home');
  toast=__qcToastWas;
`);
check('🧮 leaving the Quote screen clears the pad — the next customer never starts on old numbers', "(state.quoteLines||[]).length===0");
check('🧮 ...and it SAYS so, so a stray tap mid-quote reads as cleared, never a mystery blank', "window.__qcToasts.some(function(t){ return t.indexOf('Quote cleared')>=0; })");
run(`
  __qcToastWas=toast; window.__qcToasts=[]; toast=function(t){ window.__qcToasts.push(String(t||'')); };
  state.screen='quote'; state.quoteLines=[];
  go('home');
  toast=__qcToastWas;
`);
check('🧮 an already-empty pad clears in SILENCE (the cry-wolf rule — no toast for a no-op)', "!window.__qcToasts.some(function(t){ return t.indexOf('Quote cleared')>=0; })");
run("state.screen='home'; state.params={}; delete window.__qcToasts;");

/* 🧺 Bianca's ticket (9/28): "need wash and fold options in quote area" — by the pound and one flat load, priced exactly as Detail prices them */
section('— 🧺 wash & fold on a quote —');
run(`
  __wfqS={ rate:S().washFoldRate, load:S().washFoldLoad }; S().washFoldRate=2.75; S().washFoldLoad=30;
  __wfqVal=val; __wfqToast=toast; window.__wfqToasts=[]; toast=function(t){ window.__wfqToasts.push(String(t||'')); };
  state.quoteLines=[];
  val=function(id){ return id==='qwf'?'0':''; }; addQuoteWF(); __wfqZero=state.quoteLines.length;
  val=function(id){ return id==='qwf'?'10':''; }; addQuoteWF();
  addQuoteWFLoad(); addQuoteWFLoad();
  __wfqHtml=renderQuoteLines(); __wfqText=quoteText(); __wfqScreen=renderQuote();
  __wfqSt=storeById(state.store)||S().stores[0]; __wfqTax=Math.round(87.5*(__wfqSt.tax||0)*100)/100;
  val=__wfqVal; toast=__wfqToast;
`);
check('🧺 a blank or zero weight is refused — never a $0 wash & fold line', "__wfqZero===0 && window.__wfqToasts.some(function(t){ return /weight in pounds/.test(t); })");
check('🧺 10 lb at $2.75/lb = $27.50, and two flat loads at $30 = $60.00 on one line', "state.quoteLines.length===2 && quoteWFLine(state.quoteLines[0]).total===27.5 && state.quoteLines[1].qty===2 && quoteWFLine(state.quoteLines[1]).total===60");
check('🧺 the estimate totals them with tax like everything else (tax on everything)', "__wfqHtml.indexOf('Subtotal '+money(87.5))>=0 && __wfqHtml.indexOf('Total '+money(Math.round((87.5+87.5*(__wfqSt.tax||0))*100)/100))>=0");
check('🧺 the printed quote lists both lines whole — never cut off by the slip width', "__wfqText.indexOf('10 lb Wash & Fold ')>=0 && __wfqText.indexOf('2x Wash & Dry load ')>=0 && __wfqText.indexOf(money(87.5))>=0");
check('🧺 the Quote screen offers both options with the shop own prices', "__wfqScreen.indexOf('addQuoteWF()')>0 && __wfqScreen.indexOf('addQuoteWFLoad()')>0 && __wfqScreen.indexOf(money(2.75)+'/lb')>0 && __wfqScreen.indexOf('One load · '+money(30))>0");
run("state.quoteLines=[]; S().washFoldRate=__wfqS.rate; S().washFoldLoad=__wfqS.load; delete window.__wfqToasts;");

section('— 📦 the drop-box morning flag —');
run("window.__dbxOpenWas=SYNC.dropOpen; SYNC.dropOpen=3; window.__dbxHomeOn=renderHome().indexOf('Drop box')>=0; SYNC.dropOpen=0; window.__dbxHomeOff=renderHome().indexOf('Drop box')<0; SYNC.dropOpen=window.__dbxOpenWas;");
check('📦 Home flags overnight drops ONLY when something waits (the cry-wolf rule)', "window.__dbxHomeOn===true && window.__dbxHomeOff===true");
